  str_book_tag_faction_des_5 = "พันธมิตรพเนจรที่ไร้แบบแผนและตรงไปตรงมา ประกอบด้วยนักเดินทาง นักผจญภัย และนักล่าเงินรางวัล พวกเขาใช้ความชอบธรรมเป็นเกณฑ์ คนที่ถือเสียงข้างมากจะได้รับเลือกให้เป็นผู้นำ โดยมีลิซาร์ดโคลอสซัสเป็นฐานบัญชาการเคลื่อนที่ พวกเขาเดินทางไปทั่วท้องทะเลทรายเรดีเซลด้วยยานพาหนะผุพังที่ประกอบเองหรือดัดแปลงมา ใช้ชีวิตอย่างอิสระ และไร้เรื่องให้กังวล",
  str_book_tag_faction_des_6 = "สมาคมลับที่มีประวัติศาสตร์อันยาวนานและไม่มีอาณาเขตตายตัว สมาชิกที่บ้าคลั่งและตื่นตัวมักจะซ่อนตัวอยู่ในบรรดาเมืองต่าง ๆ ของแอสตรัล และเดินทางไปรอบ ๆ โซนสีเทาที่คลุมเครือ คอยเผยแพร่ความคิดและปรัชญาของตนเอง ว่ากันว่าทรู ออเดอร์เชื่อว่าประวัติศาสตร์และหนังสือที่เผยแพร่โดยวิหารลูโมโพลิสนั้นเป็นเรื่องโกหก พวกเขาจึงมุ่งมั่นที่จะแสวงหาความจริงที่ถูกปกปิดไว้",
  str_book_tag_faction_des_7 = "ทั่วทวีปอันกว้างใหญ่นี้มีชุมชนเล็ก ๆ มากมาย องค์กรที่ไม่ระบุชื่อ และผู้อาศัยในซากปรักหักพังโบราณ ความห่างไกล ความยืนกรานต่อความเป็นอิสระ หรือเพราะพวกเขาเป็นพเนจรตั้งแต่แรก ทำให้พวกเขาไม่ได้เป็นส่วนหนึ่งของอำนาจใด ๆ ในอารยธรรม Astral เลย พวกเขาคือ \"อิสระ\" รูปลักษณ์ และเสื้อผ้า วิถีชีวิต และขนบธรรมเนียมทางวัฒนธรรมของพวกเขาแตกต่างกัน บางคนยังไม่เปิดเผยตัวตน เช่น ทหารยามในซากปรักหักพังบางแห่ง...",
  str_book_tag_faction_des_8 = "อิคลิพส์คือองค์กรกบฏหลายเชื้อชาติที่แฝงตัวอยู่ในหลายพื้นที่ ว่ากันว่าผู้นำขององค์กรคืออิคลิพไซท์ระดับสูงที่ทรงอำนาจ อีกทั้งยังมีข่าวว่าทางองค์กรได้ครอบครององค์ความรู้ลึกลับและทรัพยากรที่ไม่ทราบที่มา ตัวองค์กรเองอ้างว่าสามารถทำให้ความทะเยอทะยานและความฝันของสมาชิกเป็นจริงได้ โดยใช้แนวคิดนี้เป็นสิ่งต่อรองเพื่อดึงดูดกบฏผู้สมคบคิดจากกองกำลังและเผ่าพันธุ์ต่าง ๆ องค์กรนี้ได้พยายามโจมตีเมืองหลายแห่งของแอสตราครั้งแล้วครั้งเล่า...",
  str_book_tag_friend_des_1 = "เจ้าหน้าที่อาวุโสส่วนใหญ่ในสหพันธรัฐอิลลูมินาล้วนเป็นระดับนายพล นายพลแต่ละคนจะสั่งการกองทัพให้เข้าต่อสู้กับศัตรูทั้งหมดที่บุกรุกสหพันธรัฐอิลลูมินา โดยทำสงครามแบบเปิดเผย",
  str_book_tag_friend_des_2 = "รับผิดชอบการพัฒนาแผนการสนับสนุนต่าง ๆ ในสหพันธรัฐอิลลูมินา รวมถึงข่าวกรอง การเฝ้าระวัง การขนส่ง การคมนาคม และการสำรวจ ซึ่งเป็นส่วนจำเป็นที่ช่วยให้ปฏิบัติการทางทหารของกองทัพเป็นไปอย่างราบรื่น",
  str_book_tag_friend_des_3 = "สถาบันวิทยาศาสตร์ที่สำคัญที่สุดของสหพันธรัฐอิลลูมินา ภายใต้การนำของนักวิทยาศาสตร์อัจฉริยะอย่างกรอนรู ที่นี่มีหน้าที่หลักในการวิจัยเกี่ยวกับกลไก วัตถุดิบ ชีววิทยา และจิตวิทยา เพื่อรักษาความเป็นผู้นำด้านเทคโนโลยีของสหพันธรัฐอิลลูมินา",
  str_book_tag_friend_des_4 = "ผู้บัญชาการอัศวิน 4 คนของลูโมโพลิส รู้จักกันในนามเทวทูตทั้งสี่ ผู้สามารถต่อกรกับอิคลิพไซท์ได้อย่างยอดเยี่ยม แสดงถึงกองกำลังอันยิ่งใหญ่ของชนชั้นสูงลูโม",
  str_book_tag_friend_des_5 = "ตัวแทนแห่งอำนาจของผู้นำแห่งลูโมโพลิส ประกอบด้วยสมาชิกของตระกูลชวาตส์เป็นแกนหลัก และหัวหน้าผู้คุ้มภัยยามราตรีอีก 2 คน ที่ผู้นำเป็นผู้แต่งตั้ง ถือเป็นศูนย์รวมอำนาจของลูโมโพลิส",
  str_book_tag_friend_des_6 = "สถาบันที่คอยผดุงกฎหมายและกฎระเบียบของลูโมโพลิส นอกจากผู้เชี่ยวชาญทางด้านกฎหมายแล้ว ที่นี่ยังมีเจ้าหน้าที่อื่น ๆ ที่คอยช่วยเรื่องการพิพากษาและการตัดสิน",
  str_book_tag_friend_des_7 = "คณะประสานเสียงของวิทยาลัยนำโดยท่านหญิงยูริอาห์ ประกอบด้วยกลุ่มคีตติงที่มีชื่อเสียงพร้อมกับนักร้องอย่างโคลอี้ ซึ่งค่อนข้างได้รับความนิยมในลูโมโพลิส",
  str_book_tag_friend_des_8 = "แก๊งที่ทรงอิทธิพลมากที่สุดในอัมบราตัน นอกจากจะเป็นแก๊งที่มีจำนวนสมาชิกมากแล้ว อีสต์วานผู้นำของพวกเขายังมีความสัมพันธ์ที่ซับซ้อนกับลูโมโพลิส เครือข่ายและความแข็งแกร่งของเขานั้นเกินกว่าจะจินตนาการได้...",
  str_book_tag_friend_des_9 = "ความโกลาหลของอัมบราตันทำให้เกิดแก๊งต่าง ๆ ขึ้นมามากมาย ทั้งแก๊งใหญ่และแก๊งเล็ก แต่ก็มีบางคนที่ไม่อยากพัวพันกับแก๊ง พวกเขามีพลังที่สามารถทำอะไรได้ด้วยตัวเอง ความเก่งกาจของคนเหล่านั้นคือที่สุดของที่สุด",
  str_book_tag_friend_des_10 = "คณะปกครองที่หละหลวม ประกอบด้วยราชินีแห่งแดนเหนือ และสมาชิกสนับสนุนอีก 4 คน มีหน้าที่หลักในการตัดสินใจเกี่ยวกับเหตุการณ์สำคัญ ๆ เช่น การอยู่รอดของนอร์ธแลนด์ และการเกิดวิกฤตดาร์กโอเวอร์",
  str_book_tag_friend_des_11 = "ตามบันทึกโบราณที่ค้นพบ พวกเขาเคยใช้พลังอันยิ่งใหญ่ จึงเชื่อว่าพวกเขาเกือบทำเป้าหมายสูงสุดได้สำเร็จ และอย่างที่คาดไว้พวกเขาได้กลายเป็นผู้นำของหลาย ๆ สังกัดในทรู ออเดอร์",
  str_book_tag_friend_des_12 = "กลุ่มที่ก่อตั้งโดยสมาชิกที่ชื่นชอบการยิงสกัดกั้น บร็อคอาจไม่ใช่นักแม่นปืนที่ดี แต่ด้วยอานิสงส์จากความสัมพันธ์กับโจนา พวกเขาจึงทำงานเข้าขากันดี หน้าที่ส่วนใหญ่คือจัดการกับศัตรูที่มารุกราน",
  str_book_tag_friend_des_13 = "ในฐานะนักร้อง 2 คนที่อยู่กลุ่มเดียวกัน เรจินาและบาร์บาร่าต้องแข่งขันกันอย่างลับ ๆ เพราะต่างมีทฤษฎีดนตรีที่ต่างกัน พวกเธอจึงจัดคอนเสิร์ตขึ้นบ่อย ๆ และนั่นคือที่มาของเทศกาลดนตรี เรดีเซล เวรนช์",
  str_book_tag_friend_des_14 = "การผนึกกำลังที่กลายเป็นทีมต่อสู้หลัก 2 ทีมในเรดีเซล เวรนช์ หน่วยนกขมิ้นมีหน้าที่ขัดขวางขบวนทัพของศัตรู ส่วนหน่วยนกเขาจะเน้นการโจมตีเป็นหลัก หลังจากการต่อสู้ที่ชุลมุนวุ่นวาย สำหรับพวกเขาแล้วมีแค่คำว่าชนะ หรือไม่ก็รีบเผ่น...",
  str_book_tag_friend_des_15 = "กิลด์ขนาดเล็กที่มีโครงสร้างไม่ชัดเจน ประกอบด้วยผู้ส่งสารและผู้นำทางที่มีทักษะ ซึ่งแต่ละคนมีหน้าที่รับผิดชอบการจัดส่งของในพื้นที่ พวกเขาติดต่อกันแค่เพียงเล็กน้อย และรู้จักกันเพียงตัวตนภายนอกเท่านั้น",
  str_book_tag_friend_des_27 = "ห้องปฏิบัติการทางชีววิทยาที่เพิ่งก่อตั้งใหม่ของสหพันธรัฐอิลลูมินามีความคืบหน้าอย่างมากภายใต้การนำของเจ้าหน้าที่วิจัยมิการ์ด นอกจากนี้เธอยังได้ว่าจ้างโจลา เบนนี่กับคุโระ และแอนเซียให้มาช่วยงาน โดยมอบหมายให้พวกเขารับผิดชอบด้านการปรึกษา การป้องกัน และการสื่อสาร",
  str_book_tag_friend_des_28 = "แม้ว่าแต่ละคนจะมีเอกลักษณ์เฉพาะตัว แต่ทหารรับจ้าง นักผจญภัย และคนเร่ร่อนเหล่านี้ล้วนมีลักษณะบางส่วนที่คล้ายสัตว์ พวกเขาเข้าขากันเหมือนสหายที่ดี",
  str_book_tag_friend_des_29 = "หลังจากทะเลาะวิวาทกันที่มุมถนน ทั้งเทสซา อาเรีย และซาริเอล ก็ได้กลายมาเป็นเพื่อนกัน รวมกับเดย์นาและโรบิน ที่เป็นสมาชิกอีก 2 คนของสเปียร์โรว์ พวกเขารวมกลุ่มกันเพื่อออกผจญภัยร่วมกัน",
  str_book_tag_friend_des_30 = "โคแร็กซ์ คุสคูตา และทาคิ เป็นสมาชิกหลักในสมาคมมือสังหารลับของอีสต์วาน และในฐานะพันธมิตรของอีสต์วาน พวกเขามีหน้าที่รับผิดชอบในการให้ความช่วยเหลือกรณีฉุกเฉิน ปกติแล้วพวกเขาจะถูกเรียกก็ต่อเมื่อแก๊งต้องเจอกับภัยคุกคามครั้งใหญ่เท่านั้น",
  str_book_tag_friend_des_31 = "ครั้งหนึ่งซิลวาเคยเป็นผู้พิทักษ์ของป่าลู่ลม และเมื่อไม่นานมานี้ซิลวาได้สร้างทีมเล็ก ๆ กับลีอาห์เพื่อพาอลิซออกไปผจญภัยทั่วทั้งดินแดน",
  str_book_tag_friend_des_32 = "ต่อให้ผ่านความทุกข์ยากมามากแค่ไหน หุบเขาตาแดงก็เป็นชื่อที่พวกเขาไม่มีวันลืม ตอนนี้พายุได้สงบลงแล้ว ดอกไม้สีขาวราวกับหิมะเบ่งบานไปทั่วอาณาบริเวณ และแล้วเช้าวันใหม่ก็มาเยือนหุบเขาตาแดง สถานที่แห่งนี้กลายเป็นบ้านหลังใหม่ที่พวกเขาสาบานว่าจะปกป้องไปตลอดชีวิตที่เหลือ",
  str_book_tag_friend_des_33 = "ไม่มีใครรู้เรื่องราวในอดีตของวีรบุรุษทั้ง 4 คนนี้ อดีตของพวกเขาที่หลงเหลืออยู่ในยุคนี้ล้วนเป็นเพียงตำนานที่กระจัดกระจายไปทั่ว ไม่มีใครรู้แม้กระทั่งชื่อจริงของพวกเขา สิ่งเดียวที่แน่ใจคือพวกเขาเป็นศัตรูตัวฉกาจของอิคลิพไซท์...",
  str_book_tag_friend_des_34 = "ต่อให้ผ่านความทุกข์ยากมามากแค่ไหน หุบเขาตาแดงก็เป็นชื่อที่พวกเขาไม่มีวันลืม ตอนนี้พายุได้สงบลงแล้ว ดอกไม้สีขาวราวกับหิมะเบ่งบานไปทั่วอาณาบริเวณ และแล้วเช้าวันใหม่ก็มาเยือนหุบเขาตาแดง สถานที่แห่งนี้ได้กลายเป็นบ้านหลังใหม่ที่พวกเขาสาบานว่าจะปกป้องไปตลอดชีวิตที่เหลือ",
  str_book_tag_friend_des_35 = "สมาชิกจำนวนมากในสังกัดที่สองได้เข้าร่วมกับทรู ออเดอร์ด้วยเหตุผลต่าง ๆ นานา บ้างก็ถึงกับเชื่อว่าตนเองเป็นเพียงแค่พันธมิตรกับภาคี อย่างไรก็ดี พวกเขาทั้งหมดมีความสัมพันธ์ที่ซับซ้อนกับวิกตอเรียแห่งสังกัดแรก และมีเป้าหมายเดียวกัน แม้อาจเป็นแค่ชั่วคราวก็ตาม...",
  str_book_tag_friend_des_36 = "สำนักงานใหญ่กิลด์เป็นส่วนสำคัญของอัมบราตัน และหากไม่มีที่นี่ กิจกรรมเชิงพาณิชย์จำนวนมากของเมืองจะตกอยู่ในสภาวะวุ่นวายและยุ่งเหยิงกว่านี้ ด้วยเหตุนี้ หัวหน้ากิลด์จึงคอยมองหาทหารรับจ้างและพันธมิตรที่ไว้ใจได้เสมอเพื่อรับผิดชอบในการปกป้องกิลด์",
  str_book_tag_friend_des_37 = "ในฐานะตัวแทนของชนชั้นสูงลูโมโพลิส พวกเขาไม่เพียงแต่มีทักษะการต่อสู้ที่น่าเกรงขามเท่านั้น แต่ยังยึดมั่นในศรัทธาของตนเองด้วยความเชื่อมั่นอย่างแรงกล้า โดยจะออกต่อสู้อย่างกล้าหาญในนามของแสงสว่างเมื่อต่อสู้กับอิคลิพไซท์",
  str_book_tag_friend_des_38 = "ทหารและเจ้าหน้าที่จำนวนนับไม่ถ้วนของสหพันธรัฐอิลลูมินามีหน้าที่รับผิดชอบในการปกป้อง ดูนไฟร์ ไลน์ ต่อสู้ในแนวหน้าเมื่อทำสงครามกับอิคลิพส์อย่างสุดกำลัง เป็นอย่างนี้มาเสมอและจะเป็นเช่นนี้ต่อไป",
  str_book_tag_friend_des_39 = "ผู้มาเยือนจากต่างโลกทั้งห้ามาท่องเที่ยวในวันพักผ่อน สำหรับพวกเขาแล้ว สนามรบที่ดุเดือดเป็นเพียงความสนุกสนานอีกอย่างในวันหยุดเท่านั้นเมื่อเทียบกับการเข้าครัว",
  str_book_tag_friend_des_40 = "ณ เกาะเมฆาซึ่งห่างไกลจากแอสตราด้วยน้ำทะเลกั้นกลาง หยกสีแดงเข้มชิ้นหนึ่งนำพาให้พวกเขาได้มารู้จักกันและร่วมกันต่อสู้เคียงบ่าเคียงไหล่ เมื่อสถานการณ์คลี่คลายลงแล้ว ทุกคนก็กลายมาเป็นเพื่อนกัน",
  str_book_tag_friend_des_41 = "สมาชิกของเรดีเซล เวรนซ์ที่ใช้เวลาส่วนใหญ่ของพวกเขาออกสำรวจและสืบสวน จะไม่มีคำสั่งให้ปฏิบัติตามอย่างเคร่งครัด พวกเขาจึงมักจะตั้งกลุ่มตามความสนใจในการเก็บข้อมูลเรื่องซาก เส้นทางการค้า และป้อมปราการใหม่ ๆ",
