  str_book_title_saiji_20107 = "ศาลเลื่อน I",
  str_book_title_saiji_20108 = "ศาลเลื่อน II",
  str_book_info1001 = "คุณกับโซรอซหลบอยู่ใต้พื้นดินเบื้องล่างมานานถึง 17 ปี ต่างก็คอยพึ่งพาอาศัยกัน ผลลัพธ์ของการบำรุงรักษาเป็นประจำทำให้คุณรู้ดีว่าการเดินเครื่องโคลอสซัสครั้งนี้จะต้องล้มเหลวแน่ ๆ เช่นเดียวกับความพยายามที่ผ่านมานับครั้งไม่ถ้วน...",
  str_book_info1002 = "แต่ทว่าวันนี้สิ่งต่าง ๆ ดูแตกต่างออกไปเมื่อจู่ ๆ ก็มีแขกไม่ได้รับเชิญบุกรุกมาอย่างกะทันหัน ความหลักแหลมคือทักษะพิเศษของคุณในฐานะชาวเคเลสไทต์ และด้วยความสามารถนี้ คุณต้องแบกรับหน้าที่ในการล้างแค้นให้กับเผ่าของคุณ...",
  str_book_info1003 = "หลังจากที่คราเคนซึ่งเป็นอิคลิพไซท์ระดับสูงได้บุกเข้ามา โคลอสซัสก็ไม่ใช่ที่สงบสุขอีกต่อไป หน้าที่ของคุณในการฝ่าวงล้อมจึงยากขึ้น คุณจะช่วยแสดงความสามารถที่ผู้นำทางคนหนึ่งควรมีเมื่อต้องเผชิญหน้ากับศัตรูที่แข็งแกร่งเป็นครั้งแรกได้หรือไม่?",
  str_book_info1004 = "เมื่อคุณก้าวเข้าสู่โลกใหม่ อิคลิพไซท์ก็จู่โจมเข้ามา พวกมันมาอยู่ที่นี่ได้ยังไงกัน?ไม่มีเวลาเหลือให้คิดอะไรมาก คุณต้องกลับไปที่โคลอสซัส และหาทางออกอื่น...",
  str_book_info1005 = "เมื่อได้เจอกับแผงควบคุมที่คุ้นเคย คุณตัดสินใจที่จะให้ไวซ์มาช่วยในขั้นตอนเดินเครื่อง คุณสอนวิธีการเล่นให้ไวซ์และเตรียมบรรเลงด้วยกัน",
  str_book_info1006 = "เมื่อได้เจอกับแผงควบคุมที่คุ้นเคย คุณตัดสินใจที่จะให้ไวซ์มาช่วยในขั้นตอนเดินเครื่อง คุณสอนวิธีการเล่นให้ไวซ์และเตรียมบรรเลงด้วยกัน",
  str_book_info1007 = "เมื่อได้เจอกับแผงควบคุมที่คุ้นเคย คุณตัดสินใจที่จะให้ไวซ์มาช่วยในขั้นตอนเดินเครื่อง คุณสอนวิธีการเล่นให้ไวซ์และเตรียมบรรเลงด้วยกัน",
  str_book_info1008 = "ด้วยความช่วยเหลือของไวซ์ ในที่สุดคุณก็เดินเครื่องโคลอสซัสได้สำเร็จ พลังงานที่ไหลไปทั่วราวกับแสงออโรร่าทำให้โคลอสซัสค่อย ๆ ทะยานขึ้นสู่โลกเบื้องบน ขอแค่อีกอึดใจเดียวคุณก็จะรอดพ้นจากอันตรายแล้ว",
  str_book_info1009 = "หลังจากเดินเครื่องโคลอสซัส ความทรงจำจากอดีตก็ถาโถมเข้ามา มันคือวันที่ผู้คนของคุณถูกเข่นฆ่าในอีราเวลเมื่อ 17 ปีที่แล้ว ในบรรดาภาพเหล่านั้นได้เผยให้เห็นภาพของคนที่คุณไม่มีทางลืมได้ลง...",
  str_book_info1010 = "ภัยคุกคามยังไม่จบ ความพ่ายแพ้ของคราเคนทรายทำให้โนซาร์ด อิคลิพไซท์ระดับสูงอีกตัวโผล่มา มันสาบานว่าจะทำลายล้างคุณให้ได้ และศัตรูจำนวนมากก็เข้ามาล้อมโซรอซเอาไว้ พร้อมที่จะจัดการคุณขณะที่ยานกำลังอุ่นเครื่อง...",
  str_book_info1011 = "หลังจากอุ่นเครื่องแล้ว พลังงานของโซรอซก็ได้ไหลไปทั่วร่างของมันอีกครั้ง มันกางปีกออกและพาคุณออกจากความมืด กลับสู่ฟากฟ้า ศัตรูถูกสลัดทิ้งเหมือนฝุ่นผง สั่นสะท้านท่ามกลางเสียงคำรามดังสนั่นของโซรอซที่ประกาศก้องถึงการฟื้นคืนชีพ...",
  str_book_info1012 = "โซรอซถูกบังคับให้ลงจอดฉุกเฉินในดินแดนรกร้างหลังจากได้รับบาดเจ็บจากการต่อสู้และบินเป็นครั้งแรก... ขณะที่คุณและไวซ์กำลังโต้เถียงกัน พวกอิคลิพไซท์ก็จู่โจมเข้ามา...",
  str_book_info1013 = "เรดีเซล เวรนช์... กลุ่มผู้รอดชีวิตที่บ้าคลั่งที่คุณบังเอิญได้พบเจอ ทำให้คุณเปิดหูเปิดตาในเรื่องการเอาชีวิตรอด มิตรภาพ และการใช้ชีวิตตามเส้นทางตัวเอง และโดยเฉพาะฝีมือการทำอาหารของพวกเขาที่ถือว่ายอดแย่เลยละ",
  str_book_info1014 = "ในเขตที่อยู่อาศัยระหว่างแสงสว่างและความมืด ผู้คนต่างต่อสู้เพื่อปกป้องบ้านของพวกเขา ก็อย่างที่แครอนว่าไว้ นอกจากอิลลูมินาแล้วยังมีออโรเรียนและผู้คนอีกมากมายที่ต่อสู้เพื่อสิ่งที่พวกเขารัก",
  str_book_info1015 = "โนซาร์ดปรากฏตัวอีกครั้ง ครั้งนี้มาพร้อมกับอิคลิพไซท์ที่มากกว่าเดิม เมืองใต้ดินหมายเลข 28 ซึ่งเป็นที่พักพิงชั่วคราวถูกทำลายจากการโจมตีที่ไม่คาดคิด เมื่อมันล่มสลาย บทใหม่ก็ถือกำเนิดขึ้น...",
  str_book_info1016 = "โนซาร์ดยังคงไล่ล่าไม่หยุด แครอนเข้ามาเป็นเป้าให้อิคลิพไซท์โจมตีเพื่อเปิดทางหลบหนีให้คุณ เขาถึงขั้นยอมกดปุ่มระเบิดตัวเอง ปุ่มสีแดง เพื่อหยุดคุณจากการทำเรื่องโง่ ๆ คุณไม่มีทางเลือกอื่นอีกแล้วนอกจากหนีไป...",
  str_book_info1017 = "แรงระเบิดที่รุนแรงทำให้เมืองใต้ดินหมายเลข 28 ถูกทำลายจนไม่เหลือซาก ขณะที่คุณเสียใจต่อการจากไปของแครอน ทันใดนั้นใครบางคนที่คุณคุ้นเคยก็ได้ปรากฏตัวขึ้น แครอนนั่นเอง เขาสามารถหลบหนีออกมาได้พร้อมฉากจบสุดอลังการ...",
  str_book_info1018 = "ขณะที่คุณกำลังจะพักผ่อน คุณได้รับสายขอความช่วยเหลือจากกลุ่มที่เหมือนจะเป็นสหายร่วมอุดมการณ์ หลังจากไปถึงที่หมาย คุณถูกหน่วยผู้พิทักษ์โคลอสซัสอย่างฟิเล็กซ์และวานี่โจมตี ซึ่งดูเหมือนจะถูกควบคุมด้วยอำนาจที่เหนือกว่า...",
  str_book_info1019 = "คุณไปที่ห้องบังคับการตามคำแนะนำของเมนเดลสัน และเอาชนะทาบาอัดโดยที่ฮิอิโระโจมตีเป็นครั้งสุดท้าย ซากุระทำให้ท้องฟ้าบานสะพรั่งไปด้วยดอกซากุระ ภาพที่สวยงามนี้เป็นสิ่งสุดท้ายที่เมนเดลสันจำได้...",
  str_book_info1020 = "ตามคำพูดสุดท้ายของเมนเดลสัน คุณต้องป้องกันไม่ให้ศัตรูที่ชื่อชูมเมอร์หาไอเทมชิ้นแรกเจอ \"โมดูลคลังปัญญา\" นี่เป็นครั้งแรกที่คุณมาเยือนลูโมโพลิส ซึ่งเป็นศูนย์กลางของอารยธรรมในแอสตรา",
  str_book_info1021 = "เนื่องจากคุณไม่สามารถเข้าไปในลูโมโพลิสได้ คุณจึงต้องผ่านลูโมโพลิสชั้นล่าง ที่นี่อาจแตกต่างจากสิ่งที่คุณจินตนาการ อันตรายแทรกซึมอยู่ทุกหนแห่ง การเดินทางคงไม่ราบรื่นแน่ ๆ",
  str_book_info1022 = "เนื่องจากไวซ์ได้จดหมายแนะนำมาก่อนหน้านี้ คุณจึงได้รับการต้อนรับเป็นการส่วนตัวจากคาร์ลีน ผู้เป็นหัวหน้าหน่วยผู้พิทักษ์ลูโมโพลิส แม้ว่าเด็กสาวผู้ไม่ยิ้มแย้มคนนี้จะเคยเป็นเพื่อนร่วมโรงเรียนของไวซ์ แต่เธอก็ดูเมินเฉยและแทบจะไม่สนใจคุณเลย...",
  str_book_info1023 = "ตัวปัญหาอย่างเชลต์และไชร์หนีไปเมืองชั้นบน แต่ถูกคุณขัดขวางไว้อย่างไร้ความปราณี อิคลิพไซท์ทั้งสองนี้พร้อมต่อสู้ แต่พวกเขาไม่รู้เลยว่าต้องแลกมาด้วยอะไรบ้าง...",
  str_book_info1024 = "คุณสรุปแผนการของชูมเมอร์พร้อมกับเหตุการณ์ลูโมโพลิสในที่ประชุม แต่เจ้าหน้าที่ของสหพันธรัฐอิลลูมินาไม่สามารถให้การสนับสนุนได้ด้วยเหตุผลบางประการ ดูเหมือนว่าคุณจะต้องจัดการกับการต่อสู้ของโมดูลถัดไปด้วยตัวเอง",
  str_book_info1025 = "เมื่อมาถึงตำแหน่งที่ซ่อนส่วนประกอบที่ 2 ไว้ตามที่ปรากฏในข้อมูลของคุณ ทันใดนั้นคุณก็พบว่าตัวเองถูกรายล้อมไปด้วยความรู้สึกแปลก ๆ ที่ก้ำกึ่งระหว่างภาพลวงตาและเสียงอันน่าหลงใหล เสียงดังกังวาลอันลึกลับที่ทำให้คุณรู้สึกยำเกรง...",
  str_book_info1026 = "คุณได้สร้างการเชื่อมโยงกับโคลอสซัสที่ตายไปนานแล้วเพื่อให้ได้มาซึ่งโมดูลที่ 2 นิมิตของอดีตชาวเคเลสไทต์ปรากฏขึ้นเบื้องหน้าคุณ ความคิดของพวกเขาเริ่มแทรกซึมเข้าไปในจิตใจของคุณอย่างช้า ๆ ราวกับท่วงทำนองซิมโฟนี",
  str_book_info1027 = "เพื่อช่วยเหลือกรอนรู คุณได้ทำข้อตกลงกับชูมเมอร์ และมอบโมดูลที่ 2 ให้ ไม่คิดเลยว่าจะชูมเมอร์จะรักษาสัญญา อาจเป็นเพราะว่าคุณเคยเป็ฯอดีตเพื่อนร่วมอุดมการณ์ จึงทำให้เธอดูเหมือนจะสงสารคุณอยู่บ้าง...",
  str_book_info1028 = "โมดูลอันสุดท้ายอยู่ในระเบียงเสียงกระซิบลึกลับ แต่เวลาเหลือน้อยเต็มที คุณต้องรีบลงมือแล้ว เป้าหมายคือห้องใต้ดินที่เต็มไปด้วยวัตถุลึกลับ และคุณไม่มีทางรู้เลยว่าจะต้องเจออะไรบ้างข้างล่างนั่น...",
  str_book_info1029 = "ทางเข้าของระเบียงเสียงกระซิบกลืนกินแสงอาทิตย์ทั้งหมดราวกับสัตว์ร้ายไร้นาม และขณะที่ลงบันไดวนคุณก็รู้สึกสังหรณ์ใจ ถ้าชูมเมอร์อยู่ที่นี่ละก็ คุณต้องรีบหน่อยแล้ว...",
  str_book_info1030 = "ในที่สุดคุณก็สามารถจัดการเกิร์ตเซิร์ดที่เคยร่วมมือกับเชลต์เพื่อขโมยโมดูลอันแรกได้ เมื่อเขารู้ความจริงเบื้องหลังการตายของเชลต์ สายตาของเขาก็บ่งบอกว่าไม่เชื่อ รู้สึกเหมือนบางส่วนของเขาได้ตายไปแล้ว ขณะที่อีกส่วนกำลังลุกเป็นไฟ...",
  str_book_info1031 = "ในส่วนลึกของระเบียงเสียงกระซิบ ชูมเมอร์ลงมือโจมตีอย่างหนักหน่วง แต่เกิร์ตเซิร์ดกลับมายืนหยัดอย่างเด็ดเดี่ยวอยู่ข้างหน้าคุณ ร่างของเขาซีดเซียวราวกับสีสันแห่งชีวิตถูกดูดกลืน ตอนนี้ไม่มีเวลามาเสียใจหรือสงสาร เรายังมีงานต้องทำ",
  str_book_info1032 = "เมื่อมีโมดูลครบทั้ง 3 อัน ชูมเมอร์ก็ได้นำโคลอสซัสสีดำเข้าโจมตีลูโมโพลิส แม้ว่าโล่ลูมินาที่แข็งแกร่งจะป้องกันเอาไว้ได้ แต่เสียงแตรแห่งการดูหมิ่นก็ดังขึ้นอีกครั้ง...",
  str_book_info1033 = "การทำงานร่วมกับเจ้าหน้าที่ของสหพันธรัฐอิลลูมินา ทำให้หนอนทรายยักษ์ มารา โซล ที่พยายามบุกเมืองลูโมโพลิสพ่ายแพ้อย่างราบคาบ ตอนนี้การจู่โจมของศัตรูอาจหยุดลงแล้ว แต่วิกฤตที่ใหญ่กว่ากำลังจะมาถึง...",
  str_book_info1034 = "ชูมเมอร์จอมอาฆาตโจมตีใส่โซรอซ คุณจำใจต้องทิ้งวิกฤติในลูโมโพลิสไว้ข้างหลัง และกลับไปที่โคลอสซัสอย่างรวดเร็ว มันคือภาพที่ควรจบลงเมื่อ 17 ปีที่แล้ว โคลอสซัสสีดำและสีขาวห้ำหั่นกันอีกครั้ง...",
  str_book_info1035 = "ชายสวมหน้ากากลึกลับยืนอยู่ข้าง ๆ ชูมเมอร์ มหาอวิดัซ เมื่อถูกวิเวียนตำหนิ เขาก็เปิดเผยใบหน้า และชื่อที่เชื่อมโยงกับสหพันธรัฐอิลลูมินาก็ผุดขึ้นมา \"ฟอร์เซคิน\"...",
  str_book_info1036 = "ก่อนที่จะทันได้เอ่ยปากพูด ชูมเมอร์ก็ชาร์จพลังจนเต็ม และพลังที่ไม่ทราบที่มาก็ตรึงทุกคนเอาไว้กับพื้น เมื่อต้องเจอกับพลังที่ไม่อาจหยุดยั้ง วิเวียนจึงตัดสินใจที่จะเสี่ยง...",
  str_book_info1037 = "\"คนแถวนี้ส่งเสียงเอะอะจัง พวกเขาเอาแต่พูดเรื่องไร้สาระ บลา บลา บลา บลา บลา...\"",
  str_book_info1038 = "ไวซ์ได้นำวัตถุแปลก ๆ ที่รู้จักกันในชื่อ \"เมล็ดพันธุ์\" ไปจากคุณตามคำสั่งของเฟาสต์ ซึ่งว่ากันว่าเป็นต้นเหตุของการเปลี่ยนสิ่งมีชีวิตให้กลายเป็นอัครสาวกแห่งความมืด และเป็นสื่อกลางในการมอบพลังชั่วร้าย...",
  str_book_info1039 = "\"ทำไมคุณไม่ยอมรับความอ่อนแอของตัวเอง? ทำไมคุณถึงไม่ยอมศิโรราบต่อพลังที่แท้จริง?\"",
  str_book_info1040 = "ปืนใหญ่ลูมินา แดโมคลีส ที่เป็นอาวุธสุดยอดของลูโมโพลิส ทำการโจมตีอวิดัซด้วยเสียงคำรามอันน่ากลัว ถึงกับทำให้ทั้งเมืองต้องเสี่ยงไปด้วย...",
  str_book_info1041 = "ลำแสงจากแดโมคลีสเปลี่ยนทิศทางโดยไม่คาดคิด และคาร์ลีนผู้ที่ขาดลูมินา ดูเหมือนจะไม่สามารถนำวิถีมันได้เพียงลำพัง ตอนนั้นเองชวาตส์ เจ้าเมืองลูโมโพลิส ก็ได้ปรากฏตัวข้างหลังเธอ ทั้งคู่จัดการปิดฉากชูมเมอร์",
  str_book_info1042 = "ขอบคุณที่คุณมีสติ อวิดัซไม่สามารถหลบลำแสงได้และถูกยิงทะลุทันที ทุกคนหยุดเคลื่อนไหวราวกับเวลาหยุดเดิน เพื่อดูจุดจบของโคลอสซัสสีดำ...",
  str_book_info1043 = "เป็นเรื่องน่าประหลาดใจยิ่งนักที่มีอิคลิพไซท์ระดับสูงอาศัยอยู่ในเมืองใต้ดินหมายเลข 80 ที่อยู่ติดกับรัตติกาลนิรันดร์ การปรากฏตัวของมันอยู่เหนือความคาดหมายของทุกคน มิหนำซ้ำยังขัดขวางแผนการของไวซ์และผู้นำทางในการซ่อมแซมโซรอซอีกด้วย",
  str_book_info1044 = "เธอเคยพลาดโอกาสมาแล้วครั้งหนึ่ง และจะไม่ยอมแพ้ในครั้งนี้ เพียงแค่ว่าเมื่อสหายเก่าของเธอถูกครอบงำด้วยความโกรธแค้นและเกลียดชัง ความทรงจำของสิ่งที่เขาต้องการปกป้องและความผูกพันฉันท์เพื่อนก็ถูกบดบังไปจนสิ้น เธอยังจะดึงสติของเพื่อนคนนี้กลับคืนมาได้หรือไม่?",
  str_book_info1045 = "ถ้าโลกใบนี้ถูกครอบงำด้วยความมืดและไม่มีแสงสว่างอีกต่อไป ฉันนี่แหละจะเป็นแสงสว่างที่ขับไล่ความมืดเหล่านั้นเอง\nนี่คือทางเลือกของไรน์ฮาร์ต เธอเลือกที่จะเป็นแสงที่ส่องสว่างให้กับทุกมุม นำความหวังมาสู่ห้วงแห่งความสิ้นหวัง",
  str_book_info2001 = "เมื่อถูกเทวทูตทั้งสี่ล้อมเอาไว้ ดูเหมือนว่าบร็อคและโจนาจะไม่มีทางหนี... แต่ทันใดนั้น โจนาก็คิดแผนหลบหนีสำหรับสถานการณ์หน้าสิ่วหน้าขวานขึ้นมาได้ กระโดดออกจากลูโมโพลิส! ไม่ว่าผลจะเป็นยังไง อย่างน้อยทั้งคู่ก็ออกมาจากลูโมโพลิสได้แล้ว...",
  str_book_info2002 = "หลังจากหนีออกมาจากลูโมโพลิส โจนาและบร็อคก็ได้ไปรวมตัวกับกองกำลังของเรดีเซล เวรนช์ ขณะที่กำลังถูกไล่ตาม พวกเขาก็ได้ทิ้งคำคมสั้น ๆ แล้วหายตัวไปในผืนทรายสีเหลือง...",
  str_book_info2003 = "โบว์ลิงเกอร์เริ่มทำลายตัวเอง และชาโรนาเกือบจะเอาชีวิตไม่รอดโดยมีฟิลีชีอยู่บนไหล่ของเธอ ในที่สุดศัตรูทั้งสองก็คืนดีกัน และร่วมมือกันแก้ไขภัยคุกคามที่ซ่อนเร้นอยู่ในเมืองแกนน่อน ฟิลิชีหาวอีกแล้ว แต่ชาโรนาไม่ได้ตำหนิเธออีกต่อไป และทั้งสองก็รอดพ้นจากแรงระเบิด",
  str_book_info2004 = "หลังจากการต่อสู้อันดุเดือด คอนนอลลีก็ได้เจ้าตัวเล็กจอมปัญหานี้มา และทำความเข้าใจใหม่เกี่ยวกับคำว่า \"บ้าน\" เป็นอีกวันในฮอลิเดย์คาเฟ่ที่ไม่ราบรื่น แต่สำหรับคอนนอลลีแล้ว มันคือชีวิตประจำวันอันแสนล้ำค่า...",
  str_book_info2005 = "นอร์ธแลนด์ ดินแดนน้ำแข็งมหัศจรรย์ที่ดวงดาวจากฟากฟ้าสาดส่องลงมาประดับประดาทะเลสาบอันใสสะอาด และที่ซึ่งหิมะแสนบริสุทธิ์ปกคลุมป่าทึบและที่ราบอันไร้ขอบเขต พระราชวังตระการตาตั้งตระหง่านท่ามกลางลมหนาว เอื้อมมือเรียวยาวและซีดขาวราวกับเทพธิดาจากสรวงสวรรค์ไปสัมผัสแสงออโรร่า",
  str_book_info2006 = "ในที่สุด ความพยายามของคาร์ลีนก็เป็นผล เมื่อเธอพุ่งหอกออกไปทะลุผ่านอุปสรรคสุดท้าย ขณะที่อิคลิพไซท์ล้มตัวลง เธอก็เสร็จสิ้นบททดสอบของเบธเลเฮมในที่สุด เส้นทางของผู้พิทักษ์นั้นลำบากและโดดเดี่ยว และสงวนไว้สำหรับผู้มีกำลังที่แท้จริงเท่านั้น อย่างไรก็ตาม เพียงแหงนมองแสงออโรร่าที่สวยงาม ก็จะเข้าใจถึงความสำคัญที่ไม่อาจโต้แย้งได้",
  str_book_info1051 = "ฟอร์เซคินและชูมเมอร์ยืนอยู่เบื้องหน้ากระสวยรักษา\nฟอร์เซคินบอกเธอว่าตราบใดที่เธอละทิ้งทุกสิ่งของการเป็นเคเลสไทต์ เธอจะได้รับพลังที่มากยิ่งกว่าเดิม\nและชูมเมอร์บอกว่า เธอได้ล้มเลิกความตั้งใจที่จะเป็นเคเลสไทต์มานานแล้ว...",
  str_book_info1052 = "เพื่อเผยที่อยู่ของชูมเมอร์และหาทางซ่อมแซมโซรอซ คุณจึงกลับไปที่บ้านเกิดของชาวเคเลสไทต์\nอีราเวล",
  str_book_info1053 = "ในที่สุด ลึกเข้าไปในอีราเวล คุณพบยานอวิดัซที่ตก\nฟอร์เซคินรออยู่ที่นี่มานานแล้ว และท่าทางเธอมีเรื่องอยากพูดกับคุณ\nหรือว่าเธอแค่... ถ่วงเวลากันนะ",
  str_book_info1054 = "ชูมเมอร์ที่ตื่นขึ้นกลืนกินอิคลิพไซท์รอบตัวอย่างละโมบ\nแม้ว่ารสชาติจะแย่น่ารังเกียจ แต่ความมุ่งมั่นที่จะล้างแค้นของเธอก็ผลักดันให้เธอข้ามผ่านความเจ็บปวดไปได้ทั้งหมด",
  str_book_info1055 = "เนื่องจากได้รับพลังใหม่เอี่ยมมา ชูมเมอร์จึงอยากให้อาจารย์ของเธอยอมรับของขวัญนี้ แต่เธอกลับถูกจองจำและไม่สามารถหลบหนีออกไปได้\nอย่างไรก็ดี พันธะเช่นนี้ไม่สามารถหยุดยั้งชูมเมอร์ได้ และเธอเชื่ออย่างยิ่งว่าพวกเคเลสไทต์จะต้องอ้อนวอนต่อเธอเพื่อขอโอกาสอีกครั้ง",
  str_book_info1056 = "อีราเวลถูกโค่นล้มโดยการปรามปรามทั้งจากภายในและภายนอก\nอิคลิพไซท์รุกรานอย่างหนักหน่วง เพื่อประกาศศักดาของอิคลิพส์ที่กำลังจะมาถึงอย่างยิ่งใหญ่",
  str_book_info1057 = "เมื่อได้รับแรงขับเคลื่อนจากความปรารถนาที่เกินควบคุม ชูมเมอร์จึงทลายขีดจำกัดของเมล็ดพันธุ์ได้ และในที่สุดฟอร์เซคินก็บรรลุเป้าหมายของเธอ\nเธอนำเมล็ดพันธุ์ไปจากชูมเมอร์และจากไปโดยไม่ลังเล",
  str_book_info1058 = "ชูมเมอร์สั่งให้อิคลิพไซท์ฆ่าทุกคนขณะที่พวกเขากำลังยุ่งอยู่กับการตามหาโมดูล\nแต่เนื่องจากเธอทำเมล็ดพันธุ์หาย ไม่นานเธอจึงถูกอิคลิพไซท์เข้าล้อมและต้องตายท่ามกลางทะเลแห่งความโกลาหลอันมืดมิด\nเธอมีจุดจบเหมือนกับความทุกข์ทรมานที่เกิดขึ้นกับพวกพ้องของเธอเมื่อสิบเจ็ดปีก่อน",
  str_book_info1059 = "ในช่วงเวลาสุดท้ายของเธอ จิตใต้สำนึกบางส่วนของชูมเมอร์ได้เข้าสู่จิตใจของคุณ\nคุณได้เห็นเงาของอิคลิพส์ แม้จะแค่ชั่วครู่ แต่ขอบเขตพลังที่คุณสัมผัสได้ก็ชัดเจนไร้ข้อกังขา...",
  str_book_info1060 = "ด้วยเสียงอันดัง ประตูนั้นค่อย ๆ เปิดออกต่อหน้าคุณ ความลับทั้งหมดที่ฝังไว้ใต้เมืองอีราเวลรอให้คุณเป็นผู้เปิดเผย",
  str_book_info1061 = "อุปกรณ์จู่โจมพิเศษได้รับการเปิดใช้งานเพื่อรับมือกับอิคลิพไซท์ แต่มันก็ตั้งเป้าหมายไปที่ออโรเรียนด้วยเช่นกัน ไวซ์ถูกทำร้ายเพราะมันพยายามที่จะปกป้องคุณ",
  str_book_info1062 = "คุณมาถึงยังพื้นที่แกนกลาง ลึกเข้าไปในฐานใต้ดิน และพบระบบวงแหวนที่เป็นตัวควบคุมฐานทั้งฐาน เครื่องจักรแปลกประหลาดนี้อาจรู้ก็ได้ว่าทำอย่างไรจึงจะช่วยชีวิตไวซ์ที่ตกอยู่ในภาวะจำศีลได้",
  str_book_info1063 = "หอคอยแห่งการหวนคืนผงาดขึ้นท่ามกลางการสั่นสะเทือนอย่างรุนแรง เผยให้เห็นรูปโฉมดั้งเดิม\n\"ที่จริงหอคอยสีขาวไม่ควรอยู่ตรงนี้ มันควรอยู่... ในที่ที่สูงกว่านี้มาก\"",
  str_book_info1064 = "หอคอยสีขาวตั้งตระหง่านกลายเป็นสิ่งก่อสร้างที่สูงที่สุดในอีราเวล คุณสามารถมองเห็นโลกทั้งใบได้เมื่ออยู่ที่จุดนี้",
  str_book_info1065 = "ความเปลี่ยนแปลงทางธรณีวิทยาที่เพิ่งเกิดขึ้นทำให้ถนนสู่คอร์ดโซนมีสภาพขรุขระและโหดร้าย ทุกก้าวย่างในอุโมงค์ที่เต็มไปด้วยกับดักเป็นไปด้วยความยากลำบาก แต่เพื่อรักษาไวซ์ คุณต้องเอาชนะอุปสรรคทุกอย่างที่ขวางทางให้ได้",
  str_book_info1066 = "บาร์ตันได้รับพลังใหม่จากคอร์ดลิงก์ ซึ่งทำให้เขาเผชิญหน้ากับฟอร์เซคินได้อีกครั้งและพลิกสถานการณ์ได้ ด้วยความช่วยเหลือของเขา คุณจึงขับไล่ฟอร์เซคินไปได้และนำตัวไวซ์เข้าสู่คอร์ดลิงก์ ด้วยความหวังว่ามันจะรักษาเธอได้...",
  str_book_info1067 = "อีราเวลพบกับวิกฤตการณ์ที่ไม่เคยเกิดขึ้นมาก่อน หอคอยแห่งการหวนคืนที่มีอิคลิพไซท์ล้อมรอบทำให้คุณนึกถึงวันที่อีราเวลถูกโจมตี แต่คราวนี้ต่างไปจากเดิม เพื่อนฝูงและพันธมิตรจากทั่วทุกสารทิศต่างพากันมาเพื่อช่วยเหลือคุณ",
  str_book_info1068 = "ไวซ์ที่เข้าสู่สภาวะจำศีลถูกนำตัวเข้าสู่คอร์ดลิงก์เพื่อรับการรักษา ให้เวลาเธอสักหน่อยและจงมีศรัทธาว่าเธอจะต้องตื่นขึ้น",
  str_book_info1069 = "คุณกับคาร์ลีนได้ทอรังดักแด้ขึ้นมาโดยใช้ชั้นการป้องกันของหอคอยแห่งการหวนคืนเพื่อปกป้องไวซ์ที่อยู่ภายในคอร์ดลิงก์ เพื่อให้แน่ใจว่าเธอจะตื่นขึ้นมาตามแผนที่วางไว้ ตอนนี้ได้เวลาแล้วที่จะทำลายดักแด้นั้น",
  str_book_info1070 = "พันธมิตรของคุณกำลังคอยกันอิคลิพไซท์ให้พ้นจากหอคอย เพื่อให้แน่ใจว่าการดำเนินการจะดำเนินไปอย่างราบรื่น การต่อสู้ได้ปะทุขึ้นระหว่างราชินีแห่งแดนเหนือผู้มาจากแดนไกลและฟิเจโล ในเวลานี้ทุกวินาทีมีค่า หาโอกาสที่จะพลิกกระแสและนำชัยชนะและความหวังมาสู่การต่อสู้ครั้งนี้",
  str_book_info1071 = "ดูเหมือนว่าไวซ์ที่ตื่นขึ้นมาจากคอร์ดลิงก์จะได้รับความสามารถใหม่ ๆ จิตใจของคุณเชื่อมโยงกันแล้วในขณะนี้ คุณคอยปกป้องเธอมาตลอด และในเวลานี้ เธอจะต่อสู้เพื่อคุณ",
  str_book_info1072 = "ตอนนี้สงครามแห่งอีราเวลสิ้นสุดลงแล้ว ทุกคนมีความเห็นแตกต่างกันว่าควรทำอย่างไรกับหอคอยแห่งการหวนคืน ในท้ายที่สุดพวกเขาก็ตกลงกันได้ หอคอยแห่งการหวนคืนเป็นของอีราเวลและเคเลสไทต์",
  str_book_info1073 = "คุณบังเอิญเจอฌอน อีกา และจ้าวที่ศูนย์การแพทย์อิลลูมินา พวกเขามาจากเมืองอันห่างไกลที่ชื่อว่า Twilight ซึ่งอยู่นอกแนวป้องกันของ Illumina...",
  str_book_info1074 = "นักวิจัยสี่คนจากสภาวิทยาศาสตร์ลับสุดยอดของอิลลูมินากำลังรอคุณอยู่ การประชุมลับครั้งนี้จะเปลี่ยนชะตากรรมของคุณและโซรอซไปอย่างไร?",
  str_book_info1075 = "คุณเห็น Soroz อีกครั้งในพื้นที่ข้อมูล มันอยู่ตรงหน้าคุณ แต่คุณไม่สามารถสัมผัสมันได้ แม้แต่ความใกล้ชิดก็เป็นเท็จ",
  str_book_info1076 = "ตามบันทึกโบราณ Colossi กลับมาจากท้องฟ้า โลกไม่คุ้นเคยมานานแล้ว ทำให้พวกเขาไม่มีทางเลือกอื่นนอกจากต้องตามหาร่องรอยของอดีต",
  str_book_info1077 = "เมื่อพายุแสงเหนืออยู่เหนือการควบคุม อัศวินจะฉีกท้องฟ้าสีแดงเข้มราวกับดาวหางสีเงินสุกใส เมื่อไม่ต้องคำนึงถึงการตกแต่งของขุนนางลูโมอีกต่อไป อัศวินผู้แข็งแกร่งเหล่านี้จึงสวมชุดเกราะเหล็กแหลมเพื่อป้องกันประชาชน",
  str_book_info1078 = "คุณเข้าสู่ Twilight และไม่รู้ว่าจะดูที่ไหน คนไร้บ้านเดินเตร่ไปตามท้องถนน พ่อค้าแม่ค้าเร่ขายของ อัศวินลูโมและทหารอิลลูมินาเดินเคียงข้างกันบนถนน",
  str_book_info1079 = "ฌอนตัดสินใจท้าทาย Axelia เพื่อดูว่าใครจะเอาชนะ Eclipsites ได้มากกว่ากัน ในที่สุด Axelia ก็ชนะ!",
  str_book_info1080 = "ยักษ์ใหญ่นี้ถูกฝังอยู่ที่นี่เป็นเวลาหลายปีจนเกือบจะรวมเข้ากับหินรอบ ๆ อย่างสมบูรณ์ ยักษ์ที่เคยทะยานสู่ท้องฟ้าสีครามเบื้องบนจะไม่สยายปีกอีกต่อไป...",
  str_book_info1081 = "เมื่อคุณกลับมา Wraith ที่คุณไม่เคยพบมาก่อนจะมาขวางทางคุณ เธอมีพลังอันยิ่งใหญ่และมีแรงจูงใจที่แปลกประหลาด เธอดูเหมือนจะต้องการทำลาย \"ความปรารถนา\" ทั้งหมดในโลก",
  str_book_info1082 = "\"เราพบกันใหม่ Caelestite ฉันจะไม่รอช้าเพราะคุณมาและมอบตัวให้ฉันแล้ว\"",
  str_book_info1083 = "เพื่อให้การทดลองและรวบรวมข้อมูลของเธอเสร็จสิ้น Forsakin ตัดสินใจใช้ Vice เพื่อเปิดเผยความลับของ Chord Link เมื่อคุณพยายามจะหยุดเธอ คุณจะถูกตรึงไว้กับพื้นโดยสัตว์เลี้ยงที่เธอพกติดตัวไปด้วยทุกที่",
  str_book_info1084 = "Yingel เล่นไพ่ตายของเธอกับ Forsakin และ Helios เธอขู่ Forsakin ด้วยการทำลาย Chord Link เมื่อเผชิญหน้ากับการดูถูกเหยียดหยามของอีกฝ่าย Yingel เหนี่ยวไก",
  str_book_info1085 = "เมื่อคิดว่าห้องทดลองถูกทำลาย Forsakin รีบละทิ้งตัวประกันของเธอเพื่อช่วยเหลือห้องทดลอง เพียงเพื่อจะรู้ว่า Yingel หลอกเธอ",
  str_book_info1086 = "Forsakin ใช้วิธีการปรับปรุงที่แตกต่างกันสามวิธีเพื่อเปลี่ยน Helios ให้กลายเป็นสิ่งมีชีวิตที่แข็งแกร่งที่สุดได้สำเร็จ ถึงเวลาแล้วที่จะทดสอบความเสถียรของวัตถุโดยการฆ่าสิ่งของ",
  str_book_info1087 = "การฝึกร่วมทางทหารจัดขึ้นตามกำหนดการ และผู้เข้าร่วมจาก Lumopolis, Illumina, Twilight และสถานที่อื่นๆ ทั้งหมดมารวมตัวกันที่นี่เพื่อต่อสู้เพื่อชิงมงกุฎ",
  str_book_info1088 = "ท่ามกลางคลื่นแห่ง Eclipsites ใน Battle Simulator ทีมของ Leo ยังคงสามารถคว้าชัยชนะมาได้ และทำให้ทุกคนตกตะลึงด้วยพลังของพวกเขา",
  str_book_info1089 = "สมาชิกในทีมของลีโอดูเหมือนจะเปิดเผยจุดอ่อนในการต่อสู้ชิงธงครั้งสุดท้าย Yingel คว้าโอกาสอันรวดเร็วนี้อย่างเด็ดขาดเพื่อยุติการต่อสู้",
  str_book_info1090 = "ทีมของ Yingel ซึ่งเป็นแชมป์ได้ส่ง Axelia เข้าร่วมการแข่งขันนิทรรศการกับ Reinhardt กระแสน้ำเชี่ยวกรากภายใต้บรรยากาศที่ดูเงียบสงบของสถานที่จัดงาน",
  str_book_info1091 = "แม้ว่าคุณจะหยุดฟิเจอรัลด์ แต่เจตภูตลึกลับก็ชิงเอาคอนโซลหลักของ Guardian One ไปและพูดบางอย่างที่คลุมเครือต่อหน้าทุกคน เธอเป็นใคร?",
  str_book_info1092 = "ในห้องสอบถามในอิลลูมินา คดีทรยศของไรน์ฮาร์ตกำลังผ่านการตรวจสอบภายในครั้งที่สาม จอมพลไรน์ฮาร์ตที่เคยเป็นที่เคารพนับถือ ตอนนี้ถูกล็อกข้อมือ และมองอยู่ที่ผู้มาเฝ้าดูอย่างเงียบเชียบ",
  str_book_info1093 = "เมื่อวราธ จอมทัพใหม่ ทำการเข้าสู่งานอย่างงดงาม ภายใต้การคุ้มครองของกองทหารยอดนักสู้และอาวุธที่ทันสมัยที่สุด: เอนจิ้น VII ทหารทั้งหลายประหลาดใจในความงดงามที่ไม่มีใครหยุดยั้งของเธอ แต่ในใจของเธอก็ยังมีความรู้สึกที่ซับซ้อนกันอยู่",
  str_book_info1094 = "บึงโคลนกัดกร่อนแผ่นดินอย่างไม่หยุดยั้ง ปล่อยเสียงแตกหักดังกระหึ่ม ดินเนินรอบ ๆ พังทลายลง พืชพันธุ์เหี่ยวใน และกลิ่นเหม็นแทรกซึมอากาศ มันเหมือนกับเครือข่ายที่ยิ่งใหญ่จับกุมสิ่งมีชีวิตที่เป็นผู้บริสุทธิ์",
  str_book_info1095 = "ภายในความโคล่อคลุ้งที่กระจายอย่างรวดเร็ว ปากสีแดงเลือดของอิคลิพไซท์ก็ปรากฏขึ้นอย่างกะทันหัน มันเดือดดุเดือดเนื้อ พร้อมที่จะกินทั้งแผ่นดินและออโรเรียน ทหารตื่นตระหนก กระจัดกระจายไปทุกทิศทาง",
  str_book_info1096 = "ถูกยัดเยียดลงในความมืดมิดที่ไม่มีขอบเขต วราธมีเพียงแสงสว่างอันริบหรี่รอบตัวที่จะพึ่งพา มันคือเมล็ดที่ติดอยู่ในหลังของเธอ เหมือนเครื่องเจาะ ที่ดูดกำลังชีวิตของเธออย่างไม่หยุดยั้ง ยิ่งเธออ่อนแอลง ยิ่งเมล็ดนั้นส่องแสงสว่างยิ่งขึ้น",
  str_book_info1097 = "การขยายตัวของเมล็ดพันธุ์เกิดขึ้นเหมือนกับการบานสะพรั่งอย่างละเอียดอ่อนของดอกไม้หนามในร่างกายของวราธ ความรู้สึกแหลมคมเหมือนโซ่เหล็กที่ขันตัวรอบตัวเธอ ดังนั้นมันเหมือนการลงโทษสำหรับการสูญเสียในการต่อสู้ของเธอ",
  str_book_info1098 = "ถึงแม้ว่า Axelia จะไม่รู้สึกความเจ็บปวดทางร่างกาย แต่ความทุกข์ทรมานทางอารมณ์ก็เพิ่มขึ้นอย่างลับๆ ทุกครั้งที่เธอเห็นทหารตก หนึ่ง, สอง... เธอนับจำนวนครั้งที่ตายเป็นความเงียบ ซึ่งทำให้เกิดภาพลวงตาว่าเธอเองตายแล้วสิบหนึ่งพันหนึ่งร้อยสิบเอ็ดครั้ง",
  str_book_info1099 = "ในท้องฟ้าสีคราม มีแสงสีขาวสว่างโผล่มาหลายเส้น โจเซลีน ขี่ม้าสีขาวอยู่บนหลังม้าสงคราม และถือดาบคม วิ่งไปข้างๆกันกับนักขี่สกายไรเดอร์ลูโม พุ่งเข้าสู่พื้นที่ติดโคลน ท้องฟ้าสะท้อนเสียงม้าร้อง",
  str_book_info1100 = "นักนำทางขับโคลอสซัสไปยังสถานที่ที่กำหนดเพื่อดำเนินภารกิจ หลังจากโคลอสซัสบินขึ้นสู่ความสูงที่ปลอดภัยสำหรับการลงที่สุดท้าย Caelestites และ Eclipsites เริ่มลงจากท้องฟ้า นี่เป็นฝันหรือเรื่องนี้เคยเกิดขึ้นจริงๆ มาก่อนหน้านี้หรือไม่?",
  str_book_info1101 = "ในท้องฟ้าที่ถูกย้อมสีแดงจากพระอาทิตย์ตกดิน ผ่านชั้นเชื้อเมฆและหมอก หลุมดำที่สามารถกลืนทุกอย่างกำลังมองคุณ มันดูเหมือนจะพยายามบอกคุณบางสิ่ง และคุณสังเกตว่ามันได้ทิ้งรอยดำๆ ในใจคุณหลังจากตื่นขึ้นมา",
  str_book_info1102 = "หลายๆเสาหินแข็งที่ดูเหมือนจะเติบโตขึ้นสู่ท้องฟ้า มีแรงบางอย่างที่ดูเหมือนจะนำพาพวกเขาเข้าสู่รูปแบบบางอย่างในอากาศ ทำไมภาพที่แบบนี้ถึงปรากฏในใจของอิลลูมินันที่แทบจะไม่เคยออกจากบ้าน?",
  str_book_info1103 = "วันหนึ่ง, หนึ่งปี... สามปี, แล้วก็สิบปี... ในยุคสงครามนั้น ยูลิสซีส์คนหนุ่มได้ค้นหาห้องหลักฐานเพื่อหวังว่าชาวออโรเรียนจะรอดชีวิต - ความหวังที่มาจากชื่อที่ถูกลบออกจากประวัติศาสตร์ของอิลลูมินา",
  str_book_info1104 = "หลังจากวิจัยเป็นเวลา 40 ปี ซึ่งใช้เวลา 20 ปีในการรวบรวมฐานข้อมูลยีนพิเศษ คลังสินค้านี้เต็มไปด้วยสิ่งประดิษฐ์ของ Ulysses ที่เตรียมไว้เพื่อสู้กับศัตรูในช่วงเวลานี้",
  str_book_info1105 = "ศัตรูกำลังวิ่งเต็มที่ในเมืองแกนนอนเพื่อค้นหาและกำจัดเคเลสไทต์ พอที่พวกเขาเข้าใกล้เคเลสไทต์ คู่หูขนาดเล็กและไม่น่าสนใจของเคเลสไทต์ก็ขัดขวางการโจมตีที่รุนแรงจากศัตรูเพื่อเคเลสไทต์โดยไม่ลังเลเลย",
  str_book_info1106 = "\"อย่าปล่อยให้พวกเขาควบคุมคุณ! ความรู้ไม่มีข้อจำกัด!\" อัลกอลตะโกนขณะที่สมองของเธอทำงานอย่างรวดเร็วกับบูล ฉันต้องการบอกทุกคนว่าพวกเขาไม่จำเป็นต้องอยู่ในโลกที่ถูกคุกคามอย่างต่อเนื่องจากสิ่งที่ไม่ทราบ",
  str_book_info1107 = "การเดินทางมักจะเต็มไปด้วยความลึกลับและมหัศจรรย์เมื่อไปกับท่านหญิงวิกตอเรีย เธอกล่าวว่าตอนนี้ที่แม่น้ำ Pristine ถูกปลุกขึ้นแล้วและ Eoria ต้องเริ่มต้นบทใหม่ ความมีอยู่พิเศษนั้นจำเป็นต้องมีเพื่อนำทางทุกคนในทางเดียวกัน",
  str_book_info3060 = "การโจมตีอันเฉียบคมเกิดขึ้นแล้ว! สโมกกี้กระโดดขึ้นสูง ก่อนที่ใครจะทันได้ตอบโต้ ลูกวอลเลย์ก็พุ่งข้ามสนามไปราวกับกระสุนปืนจากลำกล้อง โดนคู่แข่งเข้าอย่างจัง!",
  str_book_info3061 = "จู่ ๆ การแข่งขันที่แปลกประหลาดก็กลายเป็นศึกปืนฉีดน้ำ และทุกคนก็จัดชุดใหญ่ไฟกะพริบ!",
  str_book_info3062 = "บททดสอบครั้งสุดท้ายของราชันมหาสมุทรคือการแสดงริมหาด! เหล่าออโรเรียนผลัดกันแสดงบนเวที และสุดท้ายสามสหายสโมกกี้ คาร์ลีน และไวซ์ หรือ \"จุมพิตแมนติคอร์\" ก็ได้ทำการแสดงสุดอลังการที่ทำให้ผู้ชมทุกคนตื่นตะลึง",
  str_book_info3063 = "สัญญาณของความวิกฤติยังคงอยู่ และอยู่ดี ๆ เบริลก็หายตัวไป! พอคุณไปเจอเธออีกครั้ง เธอก็อยู่ท่ามกลางอันตรายอันใหญ่หลวงเสียแล้ว!",
  str_book_info3064 = "ในขณะที่กำลังสิ้นหวัง ราฟาเอลก็กระโดดมาจากหน้าผาและคว้าตัวเบริลไว้ได้กลางอากาศ แองเจิลบินได้จริง ๆ ด้วย!",
  str_book_info3065 = "หลังจากที่ราฟาเอลคว้าตัวเบริลไว้ได้ เธอก็ใช้เครื่องยนต์เจ็ตของเธอชะลอการตกของทั้งสอง ใครจะทิ้งเพื่อนได้ลงเพียงเพราะมีอันตรายถึงชีวิตกันนะ",
  str_book_info3066 = "โบนาชีอำนวยเพลงต้องห้ามบนผิวน้ำทะเลให้เหล่าอวตารศักดิ์สิทธิ์ของเธอบรรเลง ในขณะที่กำลังบรรเลงเพลงอยู่นั้น ปราสาทที่หลับใหลอยู่ก้นทะเลก็ค่อย ๆ โผล่ขึ้นด้านหลังเธอ และอุกกาบาตขนาดยักษ์ก็ตกลงมาจากฟากฟ้า พุ่งตรงไปยังผู้คน ชายหาดและโรงแรม!",
  str_book_info3067 = "ในเวลาที่ทุกอย่างดูสิ้นหวัง ก็ได้เฟลอร์นี่เองที่บังคับหุ่นยนต์ยักษ์ที่เขาเพิ่งพัฒนาขึ้นใหม่มารับมือกับการพุ่งชนของอุกกาบาตที่รุนแรงด้วยมือของเขาเอง! นี่มันพลังแปลกประหลาดประเภทไหนกันเนี่ย",
  str_book_info3068 = "วิกฤติคลี่คลายแล้ว เฟลอร์บังคับการให้เรดีเซล สตีล เอ็มเควีของเขามายืนต่อหน้าทุกคนและขวางกั้นระลอกคลื่นยักษ์เอาไว้",
