  str_book_info3077 = "ก่อนที่ทุกคนจะออกจากเมืองใต้ดินหมายเลข 24 ผู้บัญชาการแนะนำให้ถ่ายรูปหมู่เพื่อรำลึกถึงวันสำคัญนี้ ภาพถ่ายจับภาพรอยยิ้มของทหาร แสงแห่งความหวังอันไม่มีวันสิ้นสุดของเบรนท์ และความงดงามของอิลลูมินา",
  str_book_info3078 = "เมื่อเผชิญหน้ากับการโจมตีของกองทัพอิคลิพไซท์ นายทหารเบรนท์จึงวางเป้าหมายของกองพลเมืองใต้ดินหมายเลข 24 ให้ชัดเจนที่สุดเท่าที่จะทำได้... สิ่งที่ต้องทำคือเผชิญหน้ากับกองทัพอิคลิพไซท์และป้องกันเมืองใต้ดินเท่านั้น!",
  str_book_skin_info_1001 = "สิ่งต่าง ๆ มีอยู่ในโลกนี้เพราะเราเชื่อว่ามี หรือเราเชื่อในสิ่งเหล่านั้นเพราะมันมีอยู่จริงกันนะ\nไม่ว่าจะจริงหรือเท็จ เป็นเรื่องจริงหรือเรื่องที่แต่งขึ้น...\nปราสาทที่เคลเคนพูดถึงนั้นอยู่ที่ก้นทะเลจริงไหมนะ หรือจะเป็นเพียงแค่เรื่องราวอีกเรื่องหนึ่งของเขากันแน่",
  str_book_skin_info_1002 = "ไวซ์วางแผนจะหาเงินพิเศษในการเดินทาง จึงเริ่มทดลองพยายามทำอะไรที่น่าสนใจหลายอย่าง...\nในฐานะเพื่อนที่ดีอย่างคุณ ไปให้กำลังใจเธอหน่อยดีไหม หรืออาจจะให้คำแนะนำด้วยก็ได้",
  str_book_skin_info_1003 = "คาร์ลีนกลัวทะเลอย่างเห็นได้ชัด และปิดตาเมื่อเข้าสู่ห้วงน้ำ...\nโชคดีที่ได้มือของคุณยื่นไปสัมผัส ทำให้เธอมีความกล้าหาญขึ้นมาบ้าง และในที่สุดเธอก็ลืมตาขึ้นดื่มด่ำกับความงดงามของมหาสมุทรตรงหน้ากับคุณ",
  str_book_skin_info_1004 = "ของขวัญที่นำความสุขแท้จริงมาให้ได้นั้นล้ำค่ามาก นี่คือปรัชญาของเอซี่\nเพื่อตอบแทนของขวัญล้ำค่าที่คุณมอบให้ เธอได้เตรียมของอร่อยให้คุณเพียบเลย แถมยังนำมามอบให้กับมือเสียด้วย...\nปัญหาก็คือ ของขวัญพวกนี้หวานเกินไป ไม่ว่าสำหรับใครก็ตาม",
  str_book_skin_info_1005 = "บาร์ตันผู้เรือแตกลอยไปติดอยู่ที่เกาะอันห่างไกล ไม่ยอมจำนนให้กับห้วงลึกของมหาสมุทร\nตราบใดที่ยังมีลมหายใจ การฝึกจะต้องดำเนินต่อไป!\nเพื่อวันหนึ่งเขาจะได้เป็นผู้พิชิตโพ้นทะเลอีกครั้งหนึ่ง บาร์ตันกับหมาป่าขาวสองตัวของเขาวิ่งเคียงข้างกันไปตามชายหาด เหงื่อไหลท่วมด้วยพลังชีวิตที่เปี่ยมล้น",
  str_book_skin_info_1006 = "ขณะที่ฮิอิโระทอดสายตามองไปยังแดนร้าง เธอก็เปลี่ยนชุดเป็นเครื่องแบบนักเรียนวิทยาลัยทหารอิลลูมินาแบบเก่าที่คุณให้เธอไว้\nเธอมีสีหน้าที่ไม่คุ้นเคยอย่างที่สุดสำหรับตัวเธอเอง มันอ่อนโยนราวกับท้องฟ้ายามราตรีที่เต็มไปด้วยหมู่ดาว",
  str_book_skin_info_1007 = "สุสานซ่อนตัวอยู่ในส่วนลึกของป่าที่เขียวชอุ่ม\nชาโรนาบอกคุณว่าที่นี่คือสถานที่พักของชาวเมืองที่ล่วงลับ\nเธอเน้นให้เห็นความจริงที่ว่า แม้ผู้คนเหล่านั้นจะเป็นชาวเมืองของเธอ แต่ก็ไม่ใช่ครอบครัวของเธอ",
  str_book_skin_info_1008 = "ภายใต้คำสั่งของฮิอิโระ ไวซ์ได้จุดดอกไม้ไฟกำยานขึ้นเป็นครั้งแรก\nประกายไฟเล็ก ๆ แตกออกเป็นเสียงก้องท่ามกลางราตรีที่เงียบงัน และทำให้ใบหน้าของไวซ์สว่างขึ้น เต็มไปด้วยความตื่นเต้น\nถ้าช่วงเวลาเหล่านี้คงอยู่ได้ตลอดไปก็ดีสินะ",
  str_book_skin_info_1009 = "ขณะที่เปลวไฟโหมกระหน่ำ ฮีโร่ของเราพุ่งทะลุหน้าต่างโดยไม่ลังเล!\nนี่คือจุดไคลแม็กซ์อันงดงามของฉากสุดท้ายอันน่าทึ่ง\nหากคุณดูจากมุมมองของผู้ชม คุณจะต้องปรบมือดังสนั่น\nแต่น่าเสียดาย ที่คุณเป็นนักแสดงหลักในครั้งนี้",
  str_book_skin_info_1010 = "ปราสาททรายสลายตัวกลายเป็นละอองฝน คริสตัลที่ผสมอยู่ทำให้เกิดเป็นสีชมพูแต่งแต้มงดงาม แต่ฝนสีชมพูที่โปรยปรายนี้ก็มิอาจเทียบได้กับรอยยิ้มของเธอ",
  str_book_skin_info_1011 = "ไม่ว่าแพกต์จะดิ้นรนต่อสู้เพื่อหลุดพ้นจากหนามเพียงใด เงื้อมมือของมันก็แน่นขึ้นและแน่นขึ้นเท่านั้น\nทันใดนั้น คุณผลักเปิดประตูและเห็นสภาพของเธอด้วยตาตัวเอง￼\nแพกต์หน้าแดงและตะโกนว่า \"อย่ามองฉัน! ฉันจัดการเองได้!\"",
  str_book_skin_info_1012 = "ไม่มีทางหนี!\nมิการ์ดลากคุณเข้าไปในห้องของเธอ\nห้องนั่งเล่นพิลึกนี้เต็มไปด้วยพืชและเครื่องมือทางวิทยาศาสตร์และวัสดุแปลกประหลาด\nดูเหมือนว่า... ไม่น่าแปลกใจเลย",
  str_book_skin_info_1013 = "ต้นไม้เขียวปลิวไสวภายใต้ดวงอาทิตย์ตอนเที่ยง\nเส้นขนแมวฟูฟ่องกลางอากาศ\nนอนหลับสบายกลางแดด เพลิดเพลินกับความฝันอันสวยงามของแมวเหมียว",
  str_book_skin_info_1014 = "เมื่อนาฬิกาบอกเวลาเที่ยงคืน ภาพมายาวิเศษก็ค่อย ๆ ลบเลือนหาย\nชุดราตรีที่งดงามกลายเป็นผีเสื้อสลับลายที่กระพือปีกสว่างไสวกลางแสงไฟอันอบอุ่น\nจนกระทั่งการเต้นรำเพลงสุดท้ายสิ้นสุดลง",
  str_book_skin_info_1015 = "ริบบิ้นที่งดงามพลิ้วไหวในอากาศ บรรยากาศแห่งฤดูกาลค่อย ๆ ครอบคลุม\nความตื่นเต้น ความคาดหวัง และความกระวนกระวายคืบคลานเข้ามา\nหลังจากรอคอยอย่างใจจดใจจ่อกับการนับถอยหลังแต่ละนาทีและวินาที ไม่มีใครปฏิเสธความสุขในช่วงเวลานั้นได้... ในเวลาที่เราได้แกะของขวัญหลังจากที่รอมานาน!",
  str_book_skin_info_1016 = "เมื่อเสียงกึกก้องของความรื่นเริงจากแสนไกลเยื้องเข้ามาถึงชายฝั่ง มันก็ถูกลมพัดกระจัดกระจายเหนือทะเลสาบกระจกเงา\nนิคินิสก้มลงมองเหนือผิวน้ำ...\nแต่ก็ไม่พบพี่สาวของเธอที่ไหนเลย กลับมองเห็นแต่ภาพสะท้อนที่กระจ่างชัดของตัวเอง",
  str_book_skin_info_1017 = "ชีวิตเหมือนดั่งภาพมายาในกระจก\nความปรารถนา อยากได้สิ่งที่ไม่อาจเป็นของตน\nเมื่อเกิดความคิดฟุ้งซ่านในจิตใจ ทางออกที่ดีที่สุดก็คือทำสมองให้ปลอดโปร่งท่ามกลางทะเลแห่งความวุ่นวาย และดำดิ่งสู่การนอนหลับแสนสบาย",
  str_book_skin_info_1018 = "\"การละวางความกังวลไม่ได้ยากอย่างที่คิดหรอกนะคะ\"\nบริกรสาวยิ้มแย้มแจ่มใส\n\"แค่คุณมีห้องอุ่น ๆ เครื่องดื่มร้อน ๆ และใครสักคนคุยเป็นเพื่อนก็พอแล้ว\"\n\"และแน่นอนว่าต้องนอนหลับให้เพียงพอด้วยนะคะ\"",
  str_book_skin_info_1019 = "กิ้งก่าผู้กล้าหาญ! ภายใต้แสงแดดที่แผดเผาและทะเลทรายอันกว้างใหญ่ แม็กกี้ปรากฏตัวอย่างกล้าหาญและแม้กระทั่งชนนักแสดงจนกระเด็นไป ไม่เพียงแต่ทำให้ผู้ชมตกใจเท่านั้น พวกเขายังประทับใจอีกด้วย",
  str_book_skin_info_1020 = "แจ้งเตือน! อีฟอยู่ในอันตราย! หลังจากใส่ชุดแปลก ๆ นี้แล้ว ไม่ว่าอีฟจะอยู่ที่ไหน เมื่อเธอกดเครื่องมือนี้ ซินซาจะปรากฏตัวทันทีเหมือนพ่อเฒ่า... เอ้ย หมายถึงพี่ชายน่ะ",
  str_book_skin_info_1021 = "หลังจากครุ่นคิดและไตร่ตรองอยู่นานภายใต้แสงอาทิตย์ที่กำลังจะลับขอบฟ้า อูริเอลก็ตกอยู่ในห้วงความคิดที่ว่างเปล่าดังเช่นทุกครั้ง สิ่งเดียวที่จะช่วยเธอได้ก็คือการมีคุณอยู่เป็นเพื่อน ไม่ว่าผลลัพธ์จะออกมาเป็นอย่างไร สิ่งที่สำคัญคือเวลาที่อยู่ด้วยกัน",
  str_book_skin_info_1022 = "ไม่รู้ว่าเป็นนิสัยดีหรือนิสัยเสีย... กับการที่ซาริเอลทำทุกอย่างเพื่อความสมมาตร ถึงขนาดยอมเจาะรูถุงน่องดี ๆ ข้างหนึ่งเพื่อให้เกิดความสมมาตรอย่างสมบูรณ์อย่างที่เธอเรียก",
  str_book_skin_info_1023 = "คาร์ลีนเปลี่ยนชุดที่แตกต่างไปจากตัวตนเดิมที่เคร่งขรึมและจริงจังของเธออย่างสิ้นเชิงเพื่อร่วมงานปาร์ตี้ชุดนอน! แต่อย่าจ้องเธอนะ เพราะแม้แต่ผู้บัญชาการอัศวินก็ยังต้องหวั่นเกรง",
  str_book_skin_info_1024 = "ชินโนะสุเกะเป็นซามูไรจากตะวันออก เพื่อแลกกับสุขภาพที่ดีของอิฟุผู้เป็นน้องสาว เขาปฏิญาณว่าจะกำจัดเหล่าร้ายให้หมดสิ้น ระหว่างการเดินทาง เขาได้พบกับศัตรูตัวฉกาจนั่นก็คือชาวเผ่านภา ทั้งสองต่อสู้กันอย่างดุเดือด สุดท้ายใครจะเป็นผู้ชนะ?",
  str_book_skin_info_1025 = "วิเวียนสวมชุดของภูเขาเมฆาและรับบทบาทเป็นเจ้าของโรงแรมซากุระเมฆา\nชั่วคราว ด้วยความช่วยเหลือของเธอ โรงแรมเล็ก ๆ ที่มักจะเงียบเหงาแห่งนี้\nกลับมีแขกมาเข้าพักมากมาย\nอย่างไรก็ตาม เธอควรพักผ่อนให้มากกว่านี้นะ!",
  str_book_skin_info_1026 = "วราธสวมชุดรบพิเศษมาถึงยังเกาะเมฆาและเริ่มภารกิจการสืบสวนของเธอ\nเพียงแต่ว่า ชุดนี้มันไม่เด่นไปหน่อยหรือ?\n\"นี่ต้องเป็นความคิดของฮิอิโระแน่ ๆ!\" — วราธ ผู้บัญชาการกองทัพกล่าว",
  str_book_skin_info_1027 = "หญิงสาวในชุดสีสันสดใสยืนอยู่บนชานชาลาถือร่มกันแดดสีขาวพร้อมกับเขียนความปรารถนาของเธอลงบนโปสต์การ์ด นี่คงจะเป็นวันหยุดที่วิเศษมากหากไม่มีเหตุการณ์ไม่คาดฝันเกิดขึ้น แต่เชื่อเถอะว่าผู้พิพากษาสูงสุดผู้ยอดเยี่ยมคนนี้พร้อมเสมอที่จะปฏิบัติงาน!",
  str_book_skin_info_1028 = "คอนนอลลี ผู้ที่อยากจะเป็นเชียร์ลีดเดอร์ กำลังมีปัญหากับการใส่ชุดแต่งกายของเธอ ด้วยกำลังใจจากผู้คนรอบตัว เธอจึงตัดสินใจที่จะเอาชนะอุปสรรคในใจด้วยการ \"ออกกำลังกาย\" เป็นพิเศษ แต่ฝนที่ตกลงมาอย่างกะทันหันทำให้แผนการของเธอต้องหยุดชะงักไป...",
  str_book_skin_info_1029 = "ด้วยเหตุผลบางประการ ชุดแต่งกายใหม่สำหรับอีเวนต์โดยเฉพาะจึงถูกเปลี่ยนเป็นเสื้อเชิ้ตลายดอกแทน ในวันที่จัดงานอีเวนต์ แม้ว่าชุดแต่งกายของอีสต์วานจะถูกดูแคลนไปบ้าง แต่เขาก็โชว์การแสดงออกมาได้อย่างเพอร์เฟกต์และทำให้คู่ต่อสู้ของเขาต้องนิ่งอึ้งไปเลย",
  str_book_skin_info_1030 = "\"ความแข็งแกร่งเพียงเท่านั้นไม่ใช่สิ่งที่ทดแทนพลังแห่งความยุติธรรม\" ไม่จำเป็นต้องทำตามกติกาที่ไร้ความหมายในการแข่งขันที่ไม่โปร่งใส หรือใส่ใจกับอันดับปลอม แค่ให้ทุกอย่างที่คุณมีและเดินเชิดออกไปด้วยทัศนคติที่สบายใจ",
  str_book_skin_info_1031 = "ทาคิได้ขึ้นนำขณะที่แรลลี่เข้าสู่การแข่งของกลุ่มอัมบราตัน แต่ด้วยความไม่ยอมแพ้ คู่ต่อสู้ของทาคิจึงใช้ \"อาวุธร้ายแรง\" ดับเครื่องรถยนต์ของเขาเสียเลย...",
  str_book_skin_info_1032 = "ลูอิสพักผ่อนสบายอยู่บนสนามหญ้า ดื่มน้ำชายามบ่ายกับ \"เจ้านาย\" ของเธอ สำหรับเธอแล้ว ชีวิตของเมตควรจะเต็มไปด้วยความสุขสันต์และไร้เดียงสา... นี่คือสิ่งที่ลิตาบอกกับเธอ",
  str_book_skin_info_1033 = "\"ตุบ ตุบ ตุบ...\" อุบัติเหตุทำให้หัวใจของเบเธลเต้นแรงราวกับสายฟ้า มันคือความหวาดกลัวอันตราย หรือเป็นแรงบันดาลใจชั่ววูบ หรือเป็นอาการสั่นไหวของหัวใจหญิงสาวกันแน่นะ? เรื่องนี้... เราอาจจะพบคำตอบในนิยายของเบเธล",
  str_book_skin_info_1034 = "เฟลอร์หยิบขนมปังที่อบเสร็จใหม่ ๆ ก้มศีรษะลงกัดหนึ่งคำแล้วบรรจงเคี้ยวให้ละเอียด ทันใดนั้นเองเขาก็ตะลึงงันหยุดนิ่งอยู่กับที่ น้ำตาก็ไหลรินแผ่วเบา...\n\"ขอบคุณที่ช่วยให้ผมได้พบกับรสชาติที่แสนอบอุ่นนี้\"",
  str_book_skin_info_1035 = "นี่ไม่ใช่เรื่องตลก ขอย้ำอีกครั้งนะ นี่ไม่ใช่เรื่องตลก! นี่คือการฝึกยุทธวิธีของเมดอย่างกะทันหัน นักโทษที่บุกเข้าไปในคฤหาสน์จะถูกนำตัวขึ้นศาลและจำคุก เมดทุกคน รวมทั้งหัวหน้าเมด มีความมั่นใจเต็มเปี่ยมเลย",
  str_book_skin_info_1036 = "สิ่งที่บางเบาและชวนฝันช่วยให้ผ่อนคลายได้เสมอ และแม้แต่ลีโอนาเองก็ไม่เว้น เมื่อมีฟองสบู่ขนาดยักษ์ห่อหุ้มร่างกายไว้ ลีโอนาก็ดูมีจิตใจสงบขึ้นมาอย่างที่หาได้ยากยิ่ง และนี่อาจเป็นสภาพจิตใจที่เธอแสวงหามานาน",
  str_book_skin_info_1037 = "เธอมีเสน่ห์แพรวพราวและงดงามอย่างน่าทึ่งราวกับอัญมณี ใครที่ได้เห็นภาพนี้ต่างก็ไม่อาจบอกได้ว่าเสน่ห์ของเธอมาจากที่ใดกันแน่",
  str_book_skin_info_1038 = "ถ้ามีคนบนเกาะกระทำความชั่วแล้วไม่มีใครฟังคำร้องเรียนของเหยื่อ เขาสามารถระบายความคับข้องใจไปยังทะเลซึ่งจะส่งทูตไปเป็นประธานตัดสินความยุติธรรม และในครั้งนี้ ผู้ที่ถูกส่งมาก็คือเธอ...",
  str_book_skin_info_1039 = "การตอกตะปู \"สายรุ้ง\" ไว้ในกล่องไม้ เพื่อชื่นชมความงามของมันเพียงคนเดียวเป็นการกระทำที่โหดร้ายและเห็นแก่ตัวที่สุด หากคุณต้องการชื่นชมรุ้งงามนั้นจริง ๆ ก็ต้องปล่อยให้มันเต้นรำอย่างอิสระ",
  str_book_skin_info_1040 = "น้ำใส ๆ กับสัตว์น้ำที่ว่ายไปมาอย่างอิสระ... เมื่อมองดูสัตว์น้ำเหล่านี้ กรอนรูก็แทบจะลืมตัวตนของเธอและเกมที่เธอเคยรักไปเลย ในช่วงเวลานี้ เธอเป็นเพียงเด็กหญิงตัวเล็ก ๆ ที่มีความสุขเมื่อได้เห็นสิ่งที่ใจปรารถนา",
  str_book_skin_info_1041 = "ว่ายน้ำในทะเลทรายคุณพูด? ไม่มีอะไรเป็นไปไม่ได้! สมาชิกของ Rediesel Wrench กำลังจัดงานเทศกาลน้ำที่ Oasis และการส่งมอบคำขอของ Azure อย่างทันท่วงทีทำให้บรรยากาศเทศกาลขึ้นอีกระดับ",
  str_book_skin_info_1042 = "\"ฉันควรจะสละทุกชีวิตโดยไม่ต้องคิดอะไรเลย\" เดี๋ยวนะ นี่อะไรน่ะ? เล็งปืนใส่เพื่อนเก่า?! ทำอะไรน่ะชารอน! แววตาบ่งบอกว่าไม่ได้เล่นละคร...",
  str_book_skin_info_1043 = "\"คนเป็นโกหกนับพัน แต่คนตายไม่ได้บอกอะไรนอกจากความจริง น่าเสียดายที่ไม่มีใครได้ยินเสียงของพวกเขา\" โดยไม่สนใจการเหลียวมองและกระซิบของผู้อื่น สิแคร์ช่วยเปิดเผยความจริงเพื่อส่งเสียงให้ผู้ตาย",
  str_book_skin_info_1044 = "แม้ว่าเธอจะไม่ได้เป็นสมาชิกของสหพันธ์อิลลูมินา แต่เครื่องแบบนายอำเภออิลลูมินาคนใหม่ของเฮดี้ก็เติมเต็มให้เธอด้วยความมั่นใจและสำนึกในหน้าที่ ด้วยเหตุนี้ แม้แต่คำพูดของเธอก็ยังได้รับความเคารพและชื่นชมจากมวลชน",
  str_book_skin_info_1045 = "\"นี่เป็นความผิดหวังที่ยิ่งใหญ่กว่าที่ฉันคิดไว้ ... \" แม้จะอยู่ในสถานที่อันตรายที่เต็มไปด้วยอาชญากรที่แข็งกระด้าง พลังของ Revy ทำให้เธอโดดเด่นเหนือใครๆ เมื่อไม่มีใครพ่ายแพ้ในความแข็งแกร่ง การขาดการแข่งขันก็ต้องโดดเดี่ยวในบางครั้ง",
  str_book_skin_info_1046 = "\"บอส นี่สำหรับคุณ\" เมื่อมีผู้บังคับบัญชาคนที่สองและสมาชิกคนอื่นๆ พาโลมาดูเหมือนหัวหน้าแก๊ง ภายใต้การมองอย่างรวดเร็วของทุกคน เธอกำลังคิดว่าจะตอบสนองคำขอของผู้มาเยือนอย่างไร",
  str_book_skin_info_1047 = "แม้ว่าชาญ่าจะแสดงออกฝ่ายที่ดื้อดึงและเป็นเด็กผู้หญิงในเรื่อง แต่ตอนนี้เธอมุ่งมั่น รับผิดชอบ และมีความมุ่งมั่นอย่างยิ่ง เหมือนกับเบธเลเฮม และมีเสน่ห์ในทางที่แตกต่าง",
  str_book_skin_info_1048 = "รวบรวมพลังกันทุกคน เพราะ The Punisher มาแล้ว! การลงโทษในรูปแบบของไฟกระพริบและเสียงฟ้าร้องดังสนั่นมาพร้อมกับเธอขณะที่เธอแร็ปต่อหน้าคุณ! ภายใต้การสอดส่องที่เฉียบคมของเธอ จะไม่มีใครรอดไปได้!",
  str_book_skin_info_1049 = "\"งานชิ้นนี้อุทิศให้กับทุกคนในกลุ่มผู้ชม\" ดนตรีนำความอบอุ่นและคำอวยพรมาให้พวกเขาในค่ำคืนอันเหน็บหนาวนี้ และเพื่อผู้ชมคนพิเศษ",
  str_book_skin_info_1050 = "เพื่อให้ได้เปรียบ Siobhan คำนวณข้อมูลเกี่ยวกับผู้เข้าแข่งขันทั้งหมดและกำหนดกลยุทธ์ของเธอเองอย่างรวดเร็ว—เพื่อสร้างเสน่ห์ของเธอโดยใช้เสื้อผ้าและการแต่งหน้าและครอบงำการออดิชั่น",
  str_book_skin_info_1051 = "หอม? จริงจังเกินไป? บางทีท่าทางอาจเป็นเพียงส่วนหน้า พิตต์แมนแสดงด้านที่อ่อนโยนของเขาเมื่อหัวใจสองดวงโหยหากันและกัน และพิราบขาวคือเครื่องยืนยันถึงสิ่งนั้น",
  str_book_skin_info_1052 = "อัศวินสายฟ้าที่มีชื่อเสียงทำตามชื่อของเธอโดยโจมตี \"ศัตรู\" ด้วยสายฟ้าในพริบตา อย่างไรก็ตาม สิ่งที่ทำให้เธอประหลาดใจอย่างมากคือผู้ชายคนนั้นแสดงความรักต่อไมเคิลอย่างไม่ปิดบัง...",
  str_book_skin_info_1053 = "เธอเป็นทั้งเจ้าของร้านทำผมและนายธนาคารและผู้เข้าร่วมเกม ตอนนี้เจโน่เข้าใจกฎของที่นี่แล้ว หลังจากนั้นเขาแสดงเวทมนตร์ที่แท้จริงให้คู่ต่อสู้ที่น่ารังเกียจของเขาสร้างปาฏิหาริย์ที่ส่งไพ่โจ๊กเกอร์ไปยังที่ที่ควรไป",
  str_book_skin_info_1054 = "“พวกคุณทุกคน—พวกคุณถูกจับกุมทั้งหมด!” เมื่อเผชิญหน้ากับผู้ต้องสงสัยที่โง่เขลาพอที่จะพยายามสะกดรอยตามน้องสาวของเธอ Dayna เลือกใช้วิธีแก้ปัญหาที่ตรงจุดและมีประสิทธิภาพมากที่สุด นั่นคือจับกุมทุกคนที่อยู่ตรงนั้นและไม่ปล่อยใครไปแม้แต่คนเดียว",
  str_book_skin_info_1055 = "การปรากฏตัวของ Fia ในความมืดที่มองไม่เห็นนั้นอาจเป็นมังกรจริงๆ ... ? หลังจากใจเย็นลงพอสมควร เธอก็ตระหนักว่ามันเป็นเพียงอุปกรณ์บางอย่าง... แต่ใครเป็นผู้ควบคุมมัน",
  str_book_skin_info_1056 = "วิธีที่ดีที่สุดในการจัดการกับคนที่ดูหมิ่นเหยียดหยามอย่างแท้จริงคือการใช้กลอุบายสกปรกของพวกเขากับพวกเขา - ทำให้พวกเขาได้ลิ้มรสยาของพวกเขาเอง และในที่สุดเมื่อพวกเขาตระหนักว่าพวกเขาทรยศและชั่วช้าเพียงใด มันก็จะสายเกินไปแล้ว",
  str_book_skin_info_1057 = "ท่ามกลางทะเลดอกไม้ Cuscuta ที่ร่วงหล่นได้ดักจับอาชญากรที่ชั่วร้ายและลากเขาไปสู่ก้นบึ้งแห่งหายนะ ในขณะที่กลิ่นหอมจะกลายเป็นศพของคนบาป",
  str_book_skin_info_1058 = "“อย่าหนีฉันนะ” Eicy พูดด้วยรอยยิ้มไร้เดียงสาขณะที่เธอเดินผ่านฝูงชนที่คลั่งไคล้อย่างใจเย็น แม้จะเป็นผู้บงการเบื้องหลังทั้งหมด แต่ในทางของเธอเอง เธอมองว่ามันเป็นการแสดงความเมตตา",
