  str_book_skin_info_10060 = "ด้วยความเร็วแสงฟ้า ฮิอิโระดึงดาบของเธอและทำให้ผู้โจมตีกลายเป็นฝุ่น ไม่มีร่องรอยแสดงถึงการมีอยู่ของพวกเขา เสื้อผ้าสง่างามของเธอทำให้ความมีอิทธิพลที่น่าเกรงขามของเธอดูยิ่งน่าประทับใจมากขึ้น",
  str_book_skin_info_10061 = "แสงอ่อนๆจากกองไฟทำให้ใบหน้าของฮิอิโระเปลี่ยนสีอย่างแปลกประหลาด บางทีมันอาจจะเป็นสีของดอกซากุระที่บานเร็วในสถานที่ที่ห่างไกล หรือสีของอารมณ์ที่แรงกล้าที่ท่านหญิงสวยงามนี้เขินเกินไปที่จะแสดงออก",
  str_book_skin_info_10062 = "พอลลักซ์เล่าให้คุณฟังเรื่องราวในอดีตที่ทำให้เธอต้องกลายเป็นผู้ปกป้อง แต่เธอไม่ต้องการที่จะย้อนความทรงจำเหล่านั้น เพราะเธอหวังว่าจะสร้างอนาคตที่ดีกว่ากับคุณ",
  str_book_skin_info_10063 = "ในขณะที่อาเรียสนุกกับเวลาที่ยอดเยี่ยมกับคุณในฝัน แต่พวกเขาก็ต้องหายไป ความเป็นจริงได้ทำให้เธอสับสน หลังจากอาบแดดแท้และหายใจสดชื่นกับลมพัดจากทะเล อาเรียในที่สุดก็เข้าใจว่าความเอื้อเฟื้อและความสุขได้มีอยู่รอบ ๆ เธอตลอดมา",
  str_book_skin_info_10064 = "ซวนจีมอบร่มนี้ให้คุณ พร้อมกับความฝันที่มันแทนที่ ไม่ว่าจะเป็นแดนที่ห่างไกลหรือดวงดาวที่สูงอยู่ข้างบน ไม่มีอะไรที่จริงจังห่างไกลถ้าคุณปรารถนามัน",
  str_book_skin_info_10065 = "ทุกประโยค ทุกคำ ทุกตัวอักษรจากอดีต อาจเป็นเครื่องหมายที่ถูกทิ้งไว้โดยบรรพบุรุษของเราในการเดินทางสู่ความจริง สิ่งที่ทำให้แต่ละตัวอักษรเกิดขึ้นและความหมายที่มันอาจจะมี - คำตอบทั้งหมดอยู่ภายในแต่ละการขีดขวาง",
  str_book_skin_info_10066 = "มีอะไรจะสบายได้มากกว่าการนอนอยู่ที่นี่ในความสุขหรือไม่?\nไม่มีงานที่ต้องทำ, ไม่มีการต่อสู้ที่ต้องเผชิญ, และไม่จำเป็นต้องหาความหมายใด ๆ สำหรับอะไรก็ตาม—ความหมายของช่วงเวลานี้คือการปล่อยวางและสนุกสนานเพียงเท่านั้น\nดูสิ, แม้แต่นกโดฟสีขาวที่บินหวนอยู่นอกหน้าต่างของฉันก็เห็นด้วย",
  str_book_title_skin_50001 = "เที่ยวอควาเรียม",
  str_book_skin_info_50001 = "ต้องมีชุดนี้ก่อน หรือต้องมีเกมที่มีชุดนี้ก่อนกันแน่? นั่นไม่สำคัญอีกต่อไปแล้ว ที่สำคัญคือกรอนรูได้เตรียมชุดนี้ไว้เป็นพิเศษสำหรับวันหยุดพักผ่อนของเธอ และจะเข้าสู่โหมดวันหยุดทันทีหลังจากสวมใส่ แม้ว่าเธอจะไปอควาเรียม ไม่ใช่ไปทะเลก็เถอะ",
  str_book_title_skin_50002 = "แพรไหมชวนฝัน",
  str_book_title_skin_50003 = "เกิดมาเพื่อทำหน้าที่",
  str_book_title_skin_50004 = "อ้อมกอดของ Sweet Melody",
  str_book_title_skin_50005 = "ทิ่มแทงอย่างรวดเร็ว",
  str_book_saiji_info_20001 = "ในความทรงจำของอีฟ บ้านนี้เป็นบ้านที่มีความสุขสำหรับเธอ แต่มีบางสิ่งที่ขาดหายไป บางทีอาจจะมีสิ่งที่ถูกลืม หรืออาจจะมีคนที่สูญหาย...",
  str_book_saiji_info_20002 = "ความทรงจำได้ถูกเคลียร์อย่างสุดท้ายแล้ว และอีฟได้พบกันกับครอบครัวที่รักอีกครั้ง ความหวังและความสุขที่เติบโตในแสงอาทิตย์กลายเป็นดอกไม้สีขาวที่สวยงาม",
  str_book_saiji_info_20003 = "อีฟ \"ตื่น\" จากฝันที่รุนแรง และพบว่าตัวเองอยู่ในสภาพแวดล้อมที่คุ้นเคย แต่พร้อมกันก็แปลกใหม่ นี่เป็นห้องของเธอเองหรือไม่?",
  str_book_saiji_info_20004 = "เครื่องยนต์เหล็กขนาดใหญ่คลานบนยอดเขา ใครเป็นผู้สร้างเครื่องจักรแบบนี้? และเพื่อวัตถุประสงค์ใดที่ถูกสร้างขึ้น? ความรู้สึกคุ้นเคยล้างผ่านอีฟ; ภาพที่ปรากฏดูคุ้นเคย แต่เธอไม่สามารถระบุได้ว่าเคยเจอมันที่ไหนมาก่อน...",
  str_book_saiji_info_20005 = "เมื่อการพังทลายใกล้เคียงคุกคามอีฟ โล่ของดอกไม้สีขาวที่คุ้นเคยและเถาวัลย์แข็งแกร่งปรากฏขึ้นอย่างลึกลับ พวกเขาน่าจะงอกขึ้นมาจากที่ไหนกันเนี่ย?",
  str_book_saiji_info_20006 = "สองอีฟสุดท้ายจับมือกัน พร้อมที่จะเผชิญหน้ากับความเป็นจริงที่แท้จริง",
  str_book_saiji_info_20007 = "โลกที่บิดเบือนหายไป ทำให้อีฟรู้สึกโล่งใจ ถึงแม้เส้นทางเดินหน้าอาจเต็มไปด้วยอุปสรรค แต่ก็ยังสะท้อนความเป็นไปได้ที่ไม่มีขีดจำกัด",
  str_book_saiji_info_20101 = "แสงแดดส่องผ่านกระจกสี ส่องเข้าห้องที่มืดและเงียบ สร้างแสงสีที่สวยงาม มันเบา ๆ สัมผัสกับหนังตาของอิริดอน และเธอก็เปิดตาขึ้น นั่นเวลาที่เธอเห็นมัน การสะท้อนของหญิงสาวในกระจก",
  str_book_saiji_info_20102 = "อิริดอนรู้ว่าคนในกระจกไม่ใช่ตัวเธอเอง แต่ด้วยเหตุผลบางอย่าง เธอรู้สึกว่าชะตาของเธอมีความเชื่อมโยงแน่นอนกับสะท้อนในกระจก จากนั้นเปลวไฟของเทียนจุดขึ้น ส่องแสงสว่างให้เห็นภาพของนักบวชที่บริสุทธิ์และสงบบนผนัง",
  str_book_saiji_info_20103 = "อิริดอนนึกขึ้นถึงตัวตนของคนในกระจกและสุดท้ายก็ระลึกถึงตัวเธอเอง ตะเกียงที่อีกด้านจึงถูกจุดขึ้น แสดงภาพที่สง่างามและเป็นที่เคารพของผู้พิพากษาสูงสุดบนผนังภาพประดับ",
  str_book_saiji_info_20104 = "มองสะท้อนตัวเองในบ่อน้ำ อิริดอนรู้สึกถึงความสำรวมใจอย่างเฉียบขาด... สิ่งใดที่นำพาเธอมาสู่ความเป็นตัวเองในปัจจุบัน? ภาพสะท้อนในบ่อน้ำนั้นจริงๆ แล้วเป็นภาพที่เธอปรารถนาที่จะเป็นหรือไม่?",
  str_book_saiji_info_20105 = "ผู้หญิงในชุดดำข้างหน้ากระโดดลงมาดำเนินการ ตามด้วยเส้นใยหนามจำนวนมากที่พุ่งออกมาจากทุกทิศทาง อิริดอนเข้าใจว่าผู้หญิงคนนี้มีความมืดที่คมขึ้นและดำขึ้นในหัวใจของเธอกว่าหนามเหล่านี้",
  str_book_saiji_info_20106 = "ไม่ว่ากรณีใด ๆ อิริดอนก็ไม่สามารถยืนดูอยู่เฉย ๆ ขณะที่ผู้หญิงที่อยู่หน้าหน้ากำลังกระทำความผิดที่ร้ายแรงเช่นนี้",
  str_book_saiji_info_20107 = "การชนะตัวเองไม่ใช่เรื่องง่าย แต่ในที่สุด Irridon ก็สามารถทำสำเร็จได้",
  str_book_saiji_info_20108 = "การทดสอบที่ยากลำบากนี้สุดท้ายก็สิ้นสุดลง ถึงแม้ทางที่ต้องเดินยังยาวนาน แต่อิริดอนจะไม่หลงทางอีกต่อไป",
