  str_book_unlock_desc_20007 = "ได้รับเมื่อได้รับ Sketchbook ฉบับสมบูรณ์สำหรับสะสมใน Awakening in the Storm",
  str_book_unlock_desc_20101 = "ได้รับหลังจากอ่านภาคก่อนของ N1 - อัศวินในการทดสอบในระหว่างคลื่นทองคำ",
