  str_book_unlock_desc_20106 = "ได้รับหลังจากอ่านเรื่องราวก่อน N14 - การสะท้อนในการทดสอบในริมน้ำทองคำ",
  str_book_unlock_desc_20107 = "ได้รับหลังจากอ่านภาคต่อของ N15 - คำพิพากษาสุดท้ายในการพิจารณาคดีที่ระลึกทอง",
  str_book_unlock_desc_20108 = "ได้รับหลังจากอ่านภาคต่อของ N15 - คำพิพากษาสุดท้ายในการพิจารณาคดีที่ระลึกทอง",
  str_book_title_skin_10068 = "คำเชิญที่เมามันส์",
  str_book_skin_info_10068 = "\"เวลาของแม่มดมีค่ามาก และฉันไม่สามารถรอได้ ทำไม่ได้เลย\"\nหลังจากดื่มยาเวทมนตร์ อูริเอลกลายเป็นคนที่มีความริเริ่มทันที ไม่เพียงแค่มุมคุณ แต่ยังพยายามทำสิ่งที่น่ากลัวมากขึ้น...",
  str_book_title_skin_10069 = "กระดิ่งในยามพลบค่ำ",
  str_book_skin_info_10069 = "\"ฉันเองก็พึ่งรู้เห็น - และมันจริงๆ แค่เมื่อครู่ - ว่าความว่างเปล่านั้นสามารถเติมเต็มได้\"\nความร้อนจากเปลวไฟทำให้รูปทรงของแม่มดเบลอลง แต่รูปทรงไหนของเธอที่กำลังสารภาพกับคุณในตอนนี้?",
  str_book_title_skin_10067 = "ความรู้สึกของแอ็กซีเลีย",
  str_book_skin_info_10067 = "ความรู้สึกวิเศษได้กระทบ Axelia ทำให้ตัวเธอที่แตกแยกตัวเองผสมผสานกับดอกกุหลาบที่ถูกกักขังในกระปุกแก้ว ความรุนแรงที่อธิบายไม่ได้นี้ของอารมณ์จริง ๆ แล้วเป็นสัญญาณของการเปลี่ยนแปลงที่กำลังเกิดขึ้นในความคิดของเธอ",
  str_book_title_skin_10070 = "รักและหวงแหน",
  str_book_skin_info_10070 = "\"นั่นคือทุ่งข้าวสาลี! ที่เต็มไปด้วยเมล็ดข้าวสาลีสีทองที่สะบัดไปมา และฉันกำลังยืนอยู่ในทุ่งนั้น! ข้างๆฉันคือท่านหญิงที่อ่อนโยน ซึ่งหน้าของเธอไม่ชัดเจนสำหรับฉัน แต่เธอกำลังยิ้มให้ฉัน มีเด็กๆหลายคนกำลังวิ่งเล่นรอบ ๆ เรา... เสียงหัวเราะของพวกเขาสะท้อนผ่านทุ่งข้าวสาลีเหมือนเพลง.\"",
  str_book_title_skin_10071 = "พยานของไอดอลมังกร",
  str_book_title_skin_10072 = "งีบหลับตอนกลางวันของโรบิน",
  str_book_skin_info_10071 = "\"อาจจะดูเหมือนฉันหยิ่งอยู่บ้าง แต่ฉันหวังจริงๆ ว่าฉันจะเป็นคนที่คุณไว้วางใจได้\"\nภายใต้พยานของตระกูลมังกร คุณได้ยื่นคำเชิญให้กับชาโรนา",
  str_book_skin_info_10072 = "หลงอยู่ในโลกของหนังสือ โรบินก็หลับไปบนโต๊ะ แสงแดดกลางวันส่องสว่าง แต่การหลับของเธอก็ไม่ถูกรบกวนเลย",
  str_book_info1108 = "ปรารถนา",
  str_book_info1109 = "แตกความมืด",
  str_book_info1110 = "ที่ลี้ภัย",
  str_book_info1111 = "ฮาเวน - ประภาคาร",
